type S={id?:number;code:string;vehicle:string;plate:string;type:string;dueDate:string;mileage:number;cost:number;workshop:string;status:string;notes:string};
type F={id?:number;reference:string;description:string;category:string;kind:string;amount:number;date:string;location:string;status:string;paymentMethod:string;notes:string};
