const tone=(s="")=>s.includes("Dostupno")||s.includes("Plaćeno")||s.includes("Aktivan")?"green":s.includes("Iznajmljeno")||s.includes("Aktivna")||s.includes("U toku")?"blue":s.includes("Povrat")||s.includes("servisu")||s.includes("Uskoro")?"red":s.includes("Potvr")||s.includes("Rezervisano")?"violet":"amber";
function Badge({s}:{s?:string}){return <span className={`badge ${tone(s)}`}><i/>{s||"Nije određeno"}</span>}
const safePermissions=(value:unknown):string[]=>{if(Array.isArray(value))return value.filter(x=>typeof x==="string");if(typeof value!=="string")return[];try{const parsed=JSON.parse(value);return Array.isArray(parsed)?parsed.filter(x=>typeof x==="string"):[]}catch{return[]}};
const formatSerbianPhone=(value:string)=>{let digits=value.replace(/\D/g,"").slice(0,12);const international=value.trim().startsWith("+")||digits.startsWith("381");if(international){if(digits.startsWith("381"))digits=digits.slice(3);else if(digits.startsWith("0"))digits=digits.slice(1);digits=digits.slice(0,9);return "+381"+(digits?" "+digits.slice(0,2):"")+(digits.length>2?" "+digits.slice(2,5):"")+(digits.length>5?" "+digits.slice(5,9):"")}digits=digits.slice(0,10);return digits.slice(0,3)+(digits.length>3?" "+digits.slice(3,6):"")+(digits.length>6?" "+digits.slice(6,10):"")};
class AppErrorBoundary extends Component<{children:ReactNode},{failed:boolean}>{state={failed:false};static getDerivedStateFromError(){return{failed:true}}componentDidCatch(error:Error,info:ErrorInfo){console.error("DNFM UI error",error,info.componentStack)}render(){if(this.state.failed)return <div className="login"><section className="login-form"><div><div className="login-logo"><span className="brand-mark">D</span></div><h2>Aplikacija je spremna za nastavak</h2><p>Došlo je do privremene greške u prikazu. Vaši podaci su sačuvani.</p><button className="primary login-button" onClick={()=>location.reload()}>Ponovo učitaj aplikaciju</button></div></section></div>;return this.props.children}}
function useSoftDelete(entity:string){const[deleted,setDeleted]=useState<Set<string>>(new Set());useEffect(()=>{fetch(`/api/deletions?entity=${entity}`).then(r=>r.ok?r.json():Promise.reject()).then(d=>setDeleted(new Set(d.deleted||[]))).catch(()=>{})},[entity]);const remove=async(key:string,label:string)=>{if(!confirm(`Da li sigurno želite da obrišete ${label}?`))return false;const r=await fetch("/api/deletions",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({entity,key})});if(r.ok){setDeleted(x=>new Set([...x,key]));return true}alert("Brisanje nije uspelo. Pokušajte ponovo.");return false};return{deleted,remove}}
function RowMenu({label,onOpen,onDelete}:{label:string;onOpen:()=>void;onDelete:()=>void}){const[show,setShow]=useState(false);return <div className="row-menu"><button className="row-action" onClick={e=>{e.stopPropagation();setShow(x=>!x)}} aria-label={`Opcije za ${label}`}>⋯</button>{show&&<div className="row-menu-pop" onClick={e=>e.stopPropagation()}><button onClick={()=>{setShow(false);onOpen()}}>Otvori detalje</button><button className="danger" onClick={()=>{setShow(false);onDelete()}}>Obriši</button></div>}</div>}
function Head({title,sub,action,onAction}:{title:string;sub:string;action?:string;onAction?:()=>void}){return <div className="page-title"><div><h1>{title}</h1><small>{sub}</small></div>{action&&<button className="primary standalone" onClick={onAction}>+ {action}</button>}</div>}
function Kpis({items,actions}:{items:string[][];actions?:Array<()=>void>}){return <div className="kpi-grid">{items.map((x,i)=><article className={`kpi ${actions?.[i]?"clickable":""}`} key={x[0]} onClick={actions?.[i]} tabIndex={actions?.[i]?0:undefined} onKeyDown={e=>{if(actions?.[i]&&(e.key==="Enter"||e.key===" "))actions[i]()}}><div className={`kpi-icon ${x[4]}`}>◇</div><span>{x[0]}</span><strong>{x[1]}</strong><footer><small>{x[2]}</small><b className={x[4]}>{x[3]}</b></footer></article>)}</div>}
const fleetKpis=[["Ukupno vozila","0","čista flota","—","blue"],["Dostupno","0","dodajte prvo vozilo","—","green"],["Iznajmljeno","0","nema aktivnih najma","—","violet"],["Na servisu","0","nema servisnih zapisa","—","red"],["Prosečna starost","—","nema podataka","—","cyan"],["Vrednost flote","0 RSD","nema podataka","—","amber"]];
function Dashboard({go,openBooking,newReservation,addVehicle,newClient}:{go:(x:string)=>void;openBooking:(b:B)=>void;newReservation:()=>void;addVehicle:()=>void;newClient:()=>void}){const[period,setPeriod]=useState(30);const periodData:Record<number,[string,string]>={7:["0 RSD","—"],30:["0 RSD","—"],90:["0 RSD","—"]};const changePeriod=(e:React.MouseEvent)=>{e.stopPropagation();setPeriod(p=>p===7?30:p===30?90:7)};return <><div className="page-title"><div><p>PONEDELJAK, 24. AVGUST</p><h1>Dobro došli 👋</h1><small>Evo šta se danas dešava sa vašom flotom.</small></div></div><Kpis items={[["Aktivna vozila","0","nema unetih vozila","—","blue"],["Današnji prihod","0 RSD","nema transakcija","—","green"],["Iskorišćenost","0%","nema podataka","—","violet"],["Povrat danas","0","nema povrata","—","amber"],["Servis uskoro","0","nema servisa","—","red"],["Nove rezervacije","0","nema rezervacija","—","cyan"]]} actions={[()=>go("Vozila"),()=>go("Finansije"),()=>go("Izveštaji"),()=>go("Rezervacije"),()=>go("Servisi i registracije"),()=>go("Rezervacije")]}/><div className="dashboard-grid"><section className="panel revenue dashboard-link" onClick={()=>go("Finansije")}><div className="panel-head"><div><h2>Prihod</h2><p>Poslednjih {period} dana</p></div><button onClick={changePeriod}>{period} dana ⌄</button></div><div className="revenue-stat"><strong>{periodData[period][0]}</strong><span>{periodData[period][1]}</span></div><div className="line-chart"><div className="chart-fill"/></div><div className="chart-labels static"><span>Početak</span><span>1. nedelja</span><span>2. nedelja</span><span>3. nedelja</span><span>Danas</span></div></section><section className="panel activities"><div className="panel-head"><div><h2>Današnje aktivnosti</h2><p>0 aktivnosti</p></div><a onClick={()=>go("Rezervacije")}>Vidi sve</a></div>{bookings.slice(0,4).map((b,i)=><div className="activity dashboard-link" key={b.id} onClick={()=>openBooking(b)}><b>{b.from.split("•")[1]}</b><i className={i%2?"green":"blue"}/><div><span>{i%2?"Vraćanje":"Preuzimanje"}</span><strong>{b.client}</strong><small>{b.vehicle}</small></div></div>)}</section></div><div className="dashboard-lower"><section className="panel"><div className="panel-head"><div><h2>Današnje rezervacije</h2><p>Nema aktivnosti</p></div><a onClick={()=>go("Rezervacije")}>Sve rezervacije</a></div>{bookings.slice(0,3).map(b=><div className="mini-row dashboard-link" key={b.id} onClick={()=>openBooking(b)}><div className="avatar">{b.client.split(" ").map(x=>x[0]).join("")}</div><div><strong>{b.client}</strong><small>{b.vehicle}</small></div><Badge s={b.status}/><b>{b.from.split("•")[1]}</b></div>)}</section><section className="panel notice-panel"><div className="panel-head"><div><h2>Obaveštenja</h2><p>Zahtevaju pažnju</p></div></div>{([] as string[][]).map(n=><div className="notice dashboard-link" key={n[0]} onClick={()=>go(n[3])}><i className={n[2]}>◇</i><div><strong>{n[0]}</strong><small>{n[1]}</small></div><span>›</span></div>)}</section><section className="panel quick"><div className="panel-head"><div><h2>Brze akcije</h2><p>Najčešće radnje</p></div></div><button onClick={newReservation}><b>+</b>Nova rezervacija</button><button onClick={addVehicle}><b>◇</b>Dodaj vozilo</button><button onClick={newClient}><b>◉</b>Novi klijent</button></section></div></>}
function Toolbar({q,setQ}:{q:string;setQ:(x:string)=>void}){return <div className="toolbar"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Pretraži..."/></div><select><option>Svi statusi</option><option>Dostupno</option><option>Iznajmljeno</option></select><button>Više filtera ☷</button></div>}
function Vehicles({open,addTrigger=0}:{open:(v:V)=>void;addTrigger?:number}){const[q,setQ]=useState("");const{deleted,remove}=useSoftDelete("vehicles");const[status,setStatus]=useState("Svi statusi");const[location,setLocation]=useState("Sve lokacije");const[more,setMore]=useState(false);const[sortNew,setSortNew]=useState(false);const[added,setAdded]=useState<V[]>([]);const[showAdd,setShowAdd]=useState(addTrigger>0);const[loading,setLoading]=useState(true);useEffect(()=>{fetch("/api/vehicles").then(r=>r.ok?r.json():Promise.reject()).then(data=>setAdded((data.vehicles||[]).map((v:V&{km:number})=>({...v,km:`${Number(v.km).toLocaleString("sr-RS")} km`})))).catch(()=>setAdded([])).finally(()=>setLoading(false))},[]);useEffect(()=>{if(addTrigger>0)setShowAdd(true)},[addTrigger]);const all=[...added,...vehicles].filter(v=>!deleted.has(v.plate)).filter((v,i,a)=>a.findIndex(x=>x.plate===v.plate)===i);const shown=all.filter(v=>(v.name+v.plate+v.location).toLowerCase().includes(q.toLowerCase())&&(status==="Svi statusi"||v.status===status)&&(location==="Sve lokacije"||v.location.startsWith(location))).sort((a,b)=>sortNew?b.year-a.year:0);const setKpi=(s:string)=>{setStatus(s);setSortNew(false)};const avgAge=all.length?Math.round(all.reduce((sum,v)=>sum+(new Date().getFullYear()-v.year),0)/all.length):0;const vehicleKpis=[["Ukupno vozila",String(all.length),"evidentirano u bazi","uživo","blue"],["Dostupno",String(all.filter(v=>v.status==="Dostupno").length),"spremno za najam","uživo","green"],["Iznajmljeno",String(all.filter(v=>v.status==="Iznajmljeno").length),"aktivno na putu","uživo","violet"],["Na servisu",String(all.filter(v=>v.status==="Na servisu").length),"trenutno nedostupno","uživo","red"],["Prosečna starost",all.length?avgAge+" god.":"—","iz stvarnih godišta","uživo","cyan"],["Lokacije",String(new Set(all.map(v=>v.location.split(" • ")[0])).size),"aktivne poslovnice","uživo","amber"]];return <><Head title="Vozila" sub="Pregled i upravljanje kompletnom flotom." action="Dodaj vozilo" onAction={()=>setShowAdd(true)}/><Kpis items={vehicleKpis} actions={[()=>setKpi("Svi statusi"),()=>setKpi("Dostupno"),()=>setKpi("Iznajmljeno"),()=>setKpi("Na servisu"),()=>{setStatus("Svi statusi");setSortNew(true)},()=>setKpi("Svi statusi")]}/><section className="panel table-panel"><div className="toolbar"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Marka, model, tablice ili lokacija..."/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Dostupno</option><option>Iznajmljeno</option><option>Rezervisano</option><option>Na servisu</option></select><button className={more?"filter-active":""} onClick={()=>setMore(x=>!x)}>Više filtera ☷</button></div>{more&&<div className="advanced-filters"><label>Lokacija<select value={location} onChange={e=>setLocation(e.target.value)}><option>Sve lokacije</option><option>Beograd</option><option>Novi Sad</option><option>Niš</option></select></label><label><input type="checkbox" checked={sortNew} onChange={e=>setSortNew(e.target.checked)}/> Najnovija vozila prvo</label><button onClick={()=>{setQ("");setStatus("Svi statusi");setLocation("Sve lokacije");setSortNew(false)}}>Očisti filtere</button></div>}<div className="active-filter-note">Prikazano {shown.length} od {all.length} vozila{status!=="Svi statusi"?` • ${status}`:""}</div><div className="table-scroll"><table><thead><tr><th>VOZILO</th><th>STATUS</th><th>KILOMETRAŽA</th><th>LOKACIJA</th><th>SLEDEĆI SERVIS</th><th/></tr></thead><tbody>{shown.map(v=><tr key={v.plate} onClick={()=>open(v)}><td><div className="vehicle-cell"><span className="car-thumb">▰</span><div><strong>{v.name}</strong><small>{v.year} • {v.plate}</small></div></div></td><td><Badge s={v.status}/></td><td>{v.km}</td><td>{v.location}</td><td>{v.service}</td><td><RowMenu label={v.name} onOpen={()=>open(v)} onDelete={()=>{void remove(v.plate,v.name)}}/></td></tr>)}</tbody></table>{!loading&&!shown.length&&<div className="empty-table">Nema vozila koja odgovaraju izabranim filterima.</div>}{loading&&<div className="vehicle-loading">Učitavanje sačuvanih vozila…</div>}</div></section>{showAdd&&<AddVehicleModal existing={all} close={()=>setShowAdd(false)} added={v=>{setAdded(x=>[v,...x]);setShowAdd(false)}}/>}</>}
function AddVehicleModal({existing,close,added}:{existing:V[];close:()=>void;added:(v:V)=>void}){const[form,setForm]=useState({name:"",plate:"",year:"2026",km:"0",location:"Beograd • Aerodrom",status:"Dostupno",service:"Nije zakazano",vin:"",fuel:"",transmission:""});const[error,setError]=useState("");const[saving,setSaving]=useState(false);const set=(key:string,value:string)=>setForm(f=>({...f,[key]:value}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setError("");if(existing.some(v=>v.plate.replace(/\s/g,"").toLowerCase()===form.plate.replace(/\s/g,"").toLowerCase())){setError("Vozilo sa ovim registarskim tablicama već postoji.");return}setSaving(true);try{const response=await fetch("/api/vehicles",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,year:Number(form.year),km:Number(form.km)})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Vozilo nije sačuvano.");added({...data.vehicle,km:`${Number(data.vehicle.km).toLocaleString("sr-RS")} km`})}catch(e){setError(e instanceof Error?e.message:"Vozilo nije sačuvano.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close} aria-label="Zatvori">×</button><small>NOVO VOZILO</small><h2>Dodaj vozilo u flotu</h2><p className="drawer-intro">Unesite osnovne podatke. Vozilo će odmah biti sačuvano i prikazano u tabeli.</p><form onSubmit={submit}><label>Marka i model *<input required value={form.name} onChange={e=>set("name",e.target.value)} placeholder="npr. Volkswagen Passat"/></label><div className="add-form-grid"><label>Registarske tablice *<input required value={form.plate} onChange={e=>set("plate",e.target.value.toUpperCase())} placeholder="BG 1234-AA"/></label><label>Godište *<input required type="number" min="1990" max="2027" value={form.year} onChange={e=>set("year",e.target.value)}/></label><label>Kilometraža *<input required type="number" min="0" value={form.km} onChange={e=>set("km",e.target.value)}/></label><label>Lokacija *<select value={form.location} onChange={e=>set("location",e.target.value)}><option>Beograd • Aerodrom</option><option>Beograd • Novi Beograd</option><option>Beograd • Dorćol</option><option>Novi Sad • Centar</option><option>Novi Sad • Stanica</option><option>Niš • Aerodrom</option></select></label><label>Status *<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Dostupno</option><option>Rezervisano</option><option>Iznajmljeno</option><option>Na servisu</option></select></label><label>VIN<input maxLength={17} value={form.vin} onChange={e=>set("vin",e.target.value.toUpperCase())} placeholder="Broj šasije"/></label><label>Gorivo<select value={form.fuel} onChange={e=>set("fuel",e.target.value)}><option value="">Izaberite</option><option>Benzin</option><option>Dizel</option><option>Hibrid</option><option>Električno</option><option>TNG</option></select></label><label>Menjač<select value={form.transmission} onChange={e=>set("transmission",e.target.value)}><option value="">Izaberite</option><option>Manuelni</option><option>Automatski</option></select></label><label>Sledeći servis<input value={form.service} onChange={e=>set("service",e.target.value)} placeholder="npr. 12. okt 2026"/></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Dodaj vozilo"}</button></div></form></aside></div>}
function VehicleDetail({v,back}:{v:V;back:()=>void}){const[current,setCurrent]=useState(v);const[tab,setTab]=useState("Pregled");const[edit,setEdit]=useState(false);const tabs=["Pregled","Dokumentacija","Servisi","Troškovi","Rezervacije","Štete"];return <><button className="back" onClick={back}>← Sva vozila</button><div className="detail-head"><div className="big-car">▰</div><div><Badge s={current.status}/><h1>{current.name}</h1><p>{current.year} • {current.plate}</p></div><button className="outline" onClick={()=>setEdit(true)}>Uredi vozilo</button></div><div className="detail-tabs">{tabs.map(x=><button key={x} className={tab===x?"active":""} onClick={()=>setTab(x)}>{x}</button>)}</div>{tab==="Pregled"?<div className="detail-grid"><section className="panel info-card"><h2>Osnovni podaci</h2>{[["Registracija",current.plate],["VIN",current.vin||"Nije unet"],["Kilometraža",current.km],["Gorivo",current.fuel||"Nije uneto"],["Menjač",current.transmission||"Nije uneto"],["Lokacija",current.location]].map(x=><div key={x[0]}><small>{x[0]}</small><b>{x[1]}</b></div>)}</section><section className="panel health"><h2>Status vozila</h2><div className="fuel"><span>Gorivo</span><b>0%</b><i><em style={{width:"0%"}}/></i></div><div className="health-stats"><div><small>Poslednji servis</small><b>Nema podataka</b></div><div><small>Sledeći servis</small><b>{current.service}</b></div><div><small>Registracija važi do</small><b>Nema podataka</b></div></div></section><section className="panel timeline"><h2>Poslednje aktivnosti</h2>{([] as string[][]).map(x=><div key={x[0]}><i/><small>{x[0]}</small><strong>{x[1]}</strong><p>{x[2]}</p></div>)}</section></div>:<VehicleTab tab={tab} v={current}/>} {edit&&<EditVehicleModal vehicle={current} close={()=>setEdit(false)} saved={x=>{setCurrent(x);setEdit(false)}}/>}</>}
function VehicleDocuments({v}:{v:V}){const[docs,setDocs]=useState<D[]>([]);const[upload,setUpload]=useState(false);const[selected,setSelected]=useState<D|null>(null);const load=()=>fetch("/api/documents").then(r=>r.ok?r.json():Promise.reject()).then(d=>setDocs((d.documents||[]).filter((x:D)=>x.linkedTo===v.plate))).catch(()=>{});useEffect(()=>{load()},[v.plate]);return <section className="panel vehicle-tab-panel"><div className="panel-head"><div><h2>Dokumentacija</h2><p>{v.name} • {v.plate}</p></div><button className="outline" onClick={()=>setUpload(true)}>+ Dodaj dokument</button></div>{docs.map(d=><button className="vehicle-record" key={d.storageKey} onClick={()=>setSelected(d)}><span>□</span><div><strong>{d.name}</strong><small>{d.folder}{d.expiresAt?` • važi do ${new Date(`${d.expiresAt}T12:00`).toLocaleDateString("sr-Latn-RS")}`:""}</small></div><i>›</i></button>)}{!docs.length&&<div className="empty-table">Za ovo vozilo nema dodatih dokumenata.</div>}{upload&&<DocumentUpload close={()=>setUpload(false)} saved={d=>{setDocs(x=>[d,...x]);setUpload(false)}} defaultFolder="Vozila" defaultLinkedTo={v.plate}/>} {selected&&<DocumentPanel doc={selected} close={()=>setSelected(null)} changed={d=>{setDocs(x=>[d,...x.filter(y=>y.id!==d.id)]);setSelected(d)}} deleted={d=>{setDocs(x=>x.filter(y=>y.id!==d.id));setSelected(null)}}/>}</section>}
type VehicleRecord={id?:number;code?:string;reference?:string;type?:string;description?:string;client?:string;dueDate?:string;date?:string;startsAt?:string;endsAt?:string;cost?:number;amount?:number;price?:number;status?:string;notes?:string;plate?:string;vehicle?:string};
function VehicleRecordForm({tab,v,close,saved}:{tab:string;v:V;close:()=>void;saved:()=>void}){const[form,setForm]=useState({title:"",date:"",endDate:"",amount:"0",notes:""});const[saving,setSaving]=useState(false);const[error,setError]=useState("");const set=(k:string,x:string)=>setForm(f=>({...f,[k]:x}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);setError("");try{let url="";let body:Record<string,unknown>={};if(tab==="Servisi"){url="/api/services";body={vehicle:v.name,plate:v.plate,type:form.title,dueDate:form.date,mileage:Number(v.km.replace(/\D/g,"")),cost:Number(form.amount),workshop:form.notes,status:"Planirano",notes:form.notes}}else if(tab==="Troškovi"){url="/api/transactions";body={description:`[${v.plate}] ${form.title}`,category:"Troškovi vozila",kind:"Rashod",amount:Number(form.amount),date:form.date,location:v.location,status:"Plaćeno",paymentMethod:"Drugo",notes:form.notes}}else if(tab==="Rezervacije"){url="/api/reservations";body={client:form.title,vehicle:v.name,startsAt:`${form.date}T09:00`,endsAt:`${form.endDate}T09:00`,location:v.location,price:Number(form.amount),status:"Potvrđena"}}else{url="/api/damages";body={vehicle:v.name,plate:v.plate,description:form.title,date:form.date,cost:Number(form.amount),status:"Prijavljena",notes:form.notes}}const r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.error||"Zapis nije sačuvan.");saved()}catch(e){setError(e instanceof Error?e.message:"Zapis nije sačuvan.")}finally{setSaving(false)}};const titleLabel=tab==="Rezervacije"?"Klijent":tab==="Servisi"?"Tip servisa":tab==="Štete"?"Opis štete":"Opis troška";return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>NOVI ZAPIS • {tab.toUpperCase()}</small><h2>{v.name}</h2><form onSubmit={submit}><label>{titleLabel} *<input required value={form.title} onChange={e=>set("title",e.target.value)}/></label><div className="add-form-grid"><label>{tab==="Rezervacije"?"Preuzimanje":"Datum"} *<input required type="date" value={form.date} onChange={e=>set("date",e.target.value)}/></label>{tab==="Rezervacije"&&<label>Vraćanje *<input required type="date" value={form.endDate} onChange={e=>set("endDate",e.target.value)}/></label>}<label>{tab==="Rezervacije"?"Cena":"Iznos / procena"} (RSD)<input type="number" min="0" value={form.amount} onChange={e=>set("amount",e.target.value)}/></label></div>{tab!=="Rezervacije"&&<label>Napomena<textarea value={form.notes} onChange={e=>set("notes",e.target.value)}/></label>}{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Sačuvaj zapis"}</button></div></form></aside></div>}
function VehicleOperations({tab,v}:{tab:string;v:V}){const[rows,setRows]=useState<VehicleRecord[]>([]);const[add,setAdd]=useState(false);const load=()=>{const cfg=tab==="Servisi"?["/api/services","services"]:tab==="Troškovi"?["/api/transactions","transactions"]:tab==="Rezervacije"?["/api/reservations","reservations"]:["/api/damages","damages"];fetch(cfg[0]).then(r=>r.ok?r.json():Promise.reject()).then(d=>{const all=(d[cfg[1]]||[]) as VehicleRecord[];setRows(all.filter(x=>tab==="Troškovi"?x.description?.startsWith(`[${v.plate}]`):tab==="Rezervacije"?x.vehicle===v.name:x.plate===v.plate))}).catch(()=>{setRows([])})};useEffect(()=>{load()},[tab,v.plate,v.name]);return <section className="panel vehicle-tab-panel"><div className="panel-head"><div><h2>{tab}</h2><p>{v.name} • {v.plate}</p></div><button className="outline" onClick={()=>setAdd(true)}>+ Dodaj zapis</button></div>{rows.map((x,i)=>{const title=x.type||x.client||x.description?.replace(/^\[[^\]]+\]\s*/,"")||x.code||x.reference||"Zapis";const date=x.dueDate||x.date||x.startsAt?.slice(0,10)||"";const amount=x.cost??x.amount??x.price??0;return <button className="vehicle-record" key={x.code||x.reference||x.id||i}><span>□</span><div><strong>{title}</strong><small>{date}{amount?` • ${amount.toLocaleString("sr-RS")} RSD`:""}{x.status?` • ${x.status}`:""}</small></div><i>›</i></button>})}{!rows.length&&<div className="empty-table">Nema zapisa u ovom odeljku.</div>}{add&&<VehicleRecordForm tab={tab} v={v} close={()=>setAdd(false)} saved={()=>{setAdd(false);load()}}/>}</section>}
function VehicleTab({tab,v}:{tab:string;v:V}){if(tab==="Dokumentacija")return <VehicleDocuments v={v}/>;return <VehicleOperations tab={tab} v={v}/>}
function EditVehicleModal({vehicle,close,saved}:{vehicle:V;close:()=>void;saved:(v:V)=>void}){const[form,setForm]=useState({...vehicle,km:vehicle.km.replace(/[^0-9]/g,"")});const[error,setError]=useState("");const[saving,setSaving]=useState(false);const set=(k:string,value:string)=>setForm(f=>({...f,[k]:value}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setError("");setSaving(true);try{const r=await fetch("/api/vehicles",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,originalPlate:vehicle.plate,year:Number(form.year),km:Number(form.km)})});const data=await r.json();if(!r.ok)throw new Error(data.error||"Vozilo nije izmenjeno.");saved({...data.vehicle,km:`${Number(data.vehicle.km).toLocaleString("sr-RS")} km`})}catch(e){setError(e instanceof Error?e.message:"Vozilo nije izmenjeno.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>UREĐIVANJE VOZILA</small><h2>{vehicle.name}</h2><form onSubmit={submit}><label>Marka i model<input required value={form.name} onChange={e=>set("name",e.target.value)}/></label><div className="add-form-grid"><label>Tablice<input required value={form.plate} onChange={e=>set("plate",e.target.value.toUpperCase())}/></label><label>Godište<input required type="number" value={form.year} onChange={e=>set("year",e.target.value)}/></label><label>Kilometraža<input required type="number" value={form.km} onChange={e=>set("km",e.target.value)}/></label><label>Lokacija<select value={form.location} onChange={e=>set("location",e.target.value)}><option>Beograd • Aerodrom</option><option>Beograd • Novi Beograd</option><option>Beograd • Dorćol</option><option>Novi Sad • Centar</option><option>Niš • Aerodrom</option></select></label><label>Status<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Dostupno</option><option>Iznajmljeno</option><option>Rezervisano</option><option>Na servisu</option></select></label><label>VIN<input maxLength={17} value={form.vin||""} onChange={e=>set("vin",e.target.value.toUpperCase())}/></label><label>Gorivo<select value={form.fuel||""} onChange={e=>set("fuel",e.target.value)}><option value="">Izaberite</option><option>Benzin</option><option>Dizel</option><option>Hibrid</option><option>Električno</option><option>TNG</option></select></label><label>Menjač<select value={form.transmission||""} onChange={e=>set("transmission",e.target.value)}><option value="">Izaberite</option><option>Manuelni</option><option>Automatski</option></select></label><label>Sledeći servis<input value={form.service} onChange={e=>set("service",e.target.value)}/></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Sačuvaj izmene"}</button></div></form></aside></div>}
function Reservations({open,newReservation,refresh,overrides}:{open:(b:B)=>void;newReservation:()=>void;refresh:number;overrides:Record<string,string>}){const[q,setQ]=useState("");const{deleted,remove}=useSoftDelete("reservations");const[status,setStatus]=useState("Svi statusi");const[vehicle,setVehicle]=useState("Sva vozila");const[more,setMore]=useState(false);const[sortValue,setSortValue]=useState(false);const[added,setAdded]=useState<B[]>([]);const[loading,setLoading]=useState(true);useEffect(()=>{setLoading(true);fetch("/api/reservations").then(r=>r.ok?r.json():Promise.reject()).then(data=>setAdded((data.reservations||[]).map((r:{code:string;client:string;vehicle:string;startsAt:string;endsAt:string;price:number;status:string})=>({id:r.code,client:r.client,vehicle:r.vehicle,from:formatDate(r.startsAt),to:formatDate(r.endsAt),price:`${Number(r.price).toLocaleString("sr-RS")} RSD`,status:r.status})))).catch(()=>{}).finally(()=>setLoading(false))},[refresh]);const all=[...added,...bookings].filter(b=>!deleted.has(b.id)).filter((b,i,a)=>a.findIndex(x=>x.id===b.id)===i).map(b=>({...b,status:overrides[b.id]||b.status}));const shown=all.filter(b=>(b.client+b.vehicle+b.id).toLowerCase().includes(q.toLowerCase())&&(status==="Svi statusi"||b.status===status)&&(vehicle==="Sva vozila"||b.vehicle===vehicle)).sort((a,b)=>sortValue?Number(b.price.replace(/\D/g,""))-Number(a.price.replace(/\D/g,"")):0);const setKpi=(s:string)=>{setStatus(s);setSortValue(false)};const clear=()=>{setQ("");setStatus("Svi statusi");setVehicle("Sva vozila");setSortValue(false)};const totalValue=all.reduce((sum,b)=>sum+Number(b.price.replace(/\D/g,"")),0);const reservationKpis=[["Ukupno",String(all.length),"rezervacija u bazi","uživo","blue"],["Aktivne",String(all.filter(b=>b.status==="Aktivna").length),"najmova u toku","uživo","green"],["Potvrđene",String(all.filter(b=>b.status==="Potvrđena").length),"predstojeći najmovi","uživo","violet"],["Povrat danas",String(all.filter(b=>b.status==="Povrat danas").length),"zakazana povratka","uživo","red"],["Na čekanju",String(all.filter(b=>b.status==="Na čekanju").length),"zahteva za obradu","uživo","amber"],["Vrednost",totalValue.toLocaleString("sr-RS")+" RSD","svih rezervacija","uživo","cyan"]];return <><Head title="Rezervacije" sub="Sve rezervacije, preuzimanja i povrati na jednom mestu." action="Nova rezervacija" onAction={newReservation}/><Kpis items={reservationKpis} actions={[()=>setKpi("Svi statusi"),()=>setKpi("Aktivna"),()=>setKpi("Potvrđena"),()=>setKpi("Povrat danas"),()=>setKpi("Na čekanju"),()=>{setStatus("Svi statusi");setSortValue(true)}]}/><section className="panel table-panel"><div className="toolbar"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Broj rezervacije, klijent ili vozilo..."/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Na čekanju</option><option>Potvrđena</option><option>Aktivna</option><option>Povrat danas</option><option>Završena</option><option>Otkazana</option></select><button className={more?"filter-active":""} onClick={()=>setMore(x=>!x)}>Više filtera ☷</button></div>{more&&<div className="advanced-filters"><label>Vozilo<select value={vehicle} onChange={e=>setVehicle(e.target.value)}><option>Sva vozila</option>{[...new Set(all.map(b=>b.vehicle))].map(v=><option key={v}>{v}</option>)}</select></label><label><input type="checkbox" checked={sortValue} onChange={e=>setSortValue(e.target.checked)}/> Najveća vrednost prvo</label><button onClick={clear}>Očisti filtere</button></div>}<div className="active-filter-note">Prikazano {shown.length} od {all.length} rezervacija{status!=="Svi statusi"?` • ${status}`:""}</div><div className="table-scroll"><table><thead><tr><th>REZERVACIJA</th><th>KLIJENT</th><th>VOZILO</th><th>PERIOD</th><th>CENA</th><th>STATUS</th><th/></tr></thead><tbody>{shown.map(b=><tr key={b.id} onClick={()=>open(b)}><td><strong className="link">{b.id}</strong></td><td>{b.client}</td><td>{b.vehicle}</td><td><strong>{b.from}</strong><small>do {b.to}</small></td><td><strong>{b.price}</strong><small>Plaćeno karticom</small></td><td><Badge s={b.status}/></td><td><RowMenu label={b.id} onOpen={()=>open(b)} onDelete={()=>{void remove(b.id,`rezervaciju `)}}/></td></tr>)}</tbody></table>{!loading&&!shown.length&&<div className="empty-table">Nema rezervacija koje odgovaraju izabranim filterima.</div>}{loading&&<div className="vehicle-loading">Učitavanje sačuvanih rezervacija…</div>}</div></section></>}
const formatDate=(value:string)=>{const d=new Date(value);return Number.isFinite(d.getTime())?`${d.toLocaleDateString("sr-RS",{day:"2-digit",month:"short"})} • ${d.toLocaleTimeString("sr-RS",{hour:"2-digit",minute:"2-digit"})}`:value};
function NewReservationModal({close,saved}:{close:()=>void;saved:()=>void}){const[vehicleOptions,setVehicleOptions]=useState(vehicles.map(v=>v.name));const[form,setForm]=useState({client:"",vehicle:vehicles[0]?.name||"",startsAt:"",endsAt:"",location:"Beograd • Aerodrom",price:"",status:"Potvrđena"});const[error,setError]=useState("");const[saving,setSaving]=useState(false);useEffect(()=>{fetch("/api/vehicles").then(r=>r.ok?r.json():Promise.reject()).then(data=>{const opts=[...new Set((data.vehicles||[]).map((v:{name:string})=>v.name))] as string[];setVehicleOptions(opts);if(opts[0])setForm(f=>({...f,vehicle:f.vehicle||opts[0]}))}).catch(()=>{})},[]);const set=(key:string,value:string)=>setForm(f=>({...f,[key]:value}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setError("");if(new Date(form.endsAt)<=new Date(form.startsAt)){setError("Datum vraćanja mora biti posle datuma preuzimanja.");return}setSaving(true);try{const response=await fetch("/api/reservations",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,price:Number(form.price)})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Rezervacija nije sačuvana.");saved()}catch(e){setError(e instanceof Error?e.message:"Rezervacija nije sačuvana.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle reservation-form" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close} aria-label="Zatvori">×</button><small>NOVA REZERVACIJA</small><h2>Kreiraj rezervaciju</h2><p className="drawer-intro">Unesite klijenta, vozilo i period najma. Rezervacija će biti trajno sačuvana.</p><form onSubmit={submit}><label>Ime i prezime klijenta *<input required value={form.client} onChange={e=>set("client",e.target.value)} placeholder="npr. Petar Petrović"/></label><label>Vozilo *<select value={form.vehicle} onChange={e=>set("vehicle",e.target.value)}><option value="">Izaberite vozilo</option>{vehicleOptions.map(v=><option key={v}>{v}</option>)}</select></label><div className="add-form-grid"><label>Preuzimanje *<input required type="datetime-local" value={form.startsAt} onChange={e=>set("startsAt",e.target.value)}/></label><label>Vraćanje *<input required type="datetime-local" value={form.endsAt} onChange={e=>set("endsAt",e.target.value)}/></label><label>Lokacija *<select value={form.location} onChange={e=>set("location",e.target.value)}><option>Beograd • Aerodrom</option><option>Beograd • Novi Beograd</option><option>Beograd • Dorćol</option><option>Novi Sad • Centar</option><option>Novi Sad • Stanica</option><option>Niš • Aerodrom</option></select></label><label>Cena (RSD) *<input required type="number" min="0" step="100" value={form.price} onChange={e=>set("price",e.target.value)} placeholder="45000"/></label><label>Status *<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Na čekanju</option><option>Potvrđena</option><option>Aktivna</option></select></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Kreiraj rezervaciju"}</button></div></form></aside></div>}
function BookingPanel({b,close,saved}:{b:B;close:()=>void;saved:(id:string,status:string)=>void}){const[s,setS]=useState(b.status);const[saving,setSaving]=useState(false);const[error,setError]=useState("");const download=(kind:string)=>{const content=`DriveNode Fleet Manager\n${kind}\nRezervacija: ${b.id}\nKlijent: ${b.client}\nVozilo: ${b.vehicle}\nPeriod: ${b.from} — ${b.to}\nStatus: ${s}\nVrednost: ${b.price}`;const url=URL.createObjectURL(new Blob([content],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=`${kind.replace(/\s/g,"_")}_${b.id}.txt`;a.click();URL.revokeObjectURL(url)};const save=async()=>{setSaving(true);setError("");try{const r=await fetch("/api/reservations",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({code:b.id,status:s})});const data=await r.json();if(!r.ok)throw new Error(data.error||"Status nije sačuvan.");saved(b.id,s)}catch(e){setError(e instanceof Error?e.message:"Status nije sačuvan.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>REZERVACIJA {b.id}</small><h2>{b.client}</h2><Badge s={s}/><div className="booking-car"><div className="big-car">▰</div><div><b>{b.vehicle}</b><small>Rent-a-car vozilo</small></div></div><div className="trip"><div><small>PREUZIMANJE</small><b>{b.from}</b><span>Beograd</span></div><i>→</i><div><small>VRAĆANJE</small><b>{b.to}</b><span>Beograd</span></div></div><section><h3>Plaćanje</h3><div className="price-row"><span>Najam vozila</span><b>{b.price}</b></div><div className="price-row"><span>Depozit</span><b>30.000 RSD</b></div></section><section><h3>Dokumenta</h3><button className="doc-row" onClick={()=>download("Ugovor o najmu")}>□ Ugovor o najmu <span>TXT ↓</span></button><button className="doc-row" onClick={()=>download("Podaci vozačke dozvole")}>□ Podaci vozačke dozvole <span>TXT ↓</span></button></section><label className="status-control">Promeni status<select value={s} onChange={e=>setS(e.target.value)}><option>Na čekanju</option><option>Potvrđena</option><option>Aktivna</option><option>Povrat danas</option><option>Završena</option><option>Otkazana</option></select></label>{error&&<div className="form-error">{error}</div>}<button className="primary drawer-action" onClick={save} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj izmene"}</button></aside></div>}
function Calendar({open,newReservation,refresh,overrides}:{open:(b:B)=>void;newReservation:()=>void;refresh:number;overrides:Record<string,string>}){const[mode,setMode]=useState("Mesec");const[cursor,setCursor]=useState(new Date(2026,7,24));const[status,setStatus]=useState("Svi statusi");const[added,setAdded]=useState<Array<B&{date:Date}>>([]);useEffect(()=>{fetch("/api/reservations").then(r=>r.ok?r.json():Promise.reject()).then(data=>setAdded((data.reservations||[]).map((r:{code:string;client:string;vehicle:string;startsAt:string;endsAt:string;price:number;status:string})=>({id:r.code,client:r.client,vehicle:r.vehicle,from:formatDate(r.startsAt),to:formatDate(r.endsAt),price:`${Number(r.price).toLocaleString("sr-RS")} RSD`,status:r.status,date:new Date(r.startsAt)})))).catch(()=>{})},[refresh]);const demo=bookings.map((b,i)=>({...b,status:overrides[b.id]||b.status,date:new Date(2026,7,[24,24,24,25,26][i],[9,11,13,8,10][i])}));const events=[...added,...demo].filter((b,i,a)=>a.findIndex(x=>x.id===b.id)===i).filter(b=>status==="Svi statusi"||b.status===status);const same=(a:Date,b:Date)=>a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate();const move=(direction:number)=>setCursor(d=>{const n=new Date(d);if(mode==="Mesec")n.setMonth(n.getMonth()+direction);else n.setDate(n.getDate()+direction*(mode==="Nedelja"?7:1));return n});const today=()=>setCursor(new Date(2026,7,24));const monthStart=new Date(cursor.getFullYear(),cursor.getMonth(),1);const gridStart=new Date(monthStart);gridStart.setDate(1-((monthStart.getDay()+6)%7));const monthDays=Array.from({length:42},(_,i)=>{const d=new Date(gridStart);d.setDate(gridStart.getDate()+i);return d});const weekStart=new Date(cursor);weekStart.setDate(cursor.getDate()-((cursor.getDay()+6)%7));const weekDays=Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(weekStart.getDate()+i);return d});const title=mode==="Mesec"?cursor.toLocaleDateString("sr-Latn-RS",{month:"long",year:"numeric"}):mode==="Nedelja"?`${weekDays[0].toLocaleDateString("sr-Latn-RS",{day:"numeric",month:"short"})} — ${weekDays[6].toLocaleDateString("sr-Latn-RS",{day:"numeric",month:"short",year:"numeric"})}`:cursor.toLocaleDateString("sr-Latn-RS",{weekday:"long",day:"numeric",month:"long",year:"numeric"});const eventButton=(b:B)=><button key={b.id} className={`calendar-event ${tone(b.status)}`} onClick={e=>{e.stopPropagation();open(b)}}><b>{b.from.split("•")[1]||"09:00"}</b> {b.vehicle.replace("Volkswagen ","")} • {b.client.split(" ")[0]}</button>;return <><Head title="Kalendar rezervacija" sub="Planirajte dostupnost flote i raspored preuzimanja." action="Nova rezervacija" onAction={newReservation}/><div className="calendar-toolbar"><div className="segmented">{["Mesec","Nedelja","Dan"].map(x=><button onClick={()=>setMode(x)} className={mode===x?"active":""} key={x}>{x}</button>)}</div><div className="calendar-nav"><button onClick={()=>move(-1)} aria-label="Prethodni period">‹</button><button onClick={today}>Danas</button><button onClick={()=>move(1)} aria-label="Sledeći period">›</button></div><h2>{title}</h2><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Na čekanju</option><option>Potvrđena</option><option>Aktivna</option><option>Povrat danas</option><option>Završena</option><option>Otkazana</option></select></div>{mode==="Mesec"?<section className="calendar panel"><div className="weekdays">{["PON","UTO","SRE","ČET","PET","SUB","NED"].map(x=><b key={x}>{x}</b>)}</div><div className="calendar-grid">{monthDays.map(d=><div className={`${same(d,new Date(2026,7,24))?"today ":""}${d.getMonth()!==cursor.getMonth()?"outside":""}`} key={d.toISOString()} onClick={()=>{setCursor(d);setMode("Dan")}}><span>{d.getDate()}</span>{events.filter(b=>same(b.date,d)).map(eventButton)}</div>)}</div></section>:mode==="Nedelja"?<section className="panel week-calendar">{weekDays.map(d=><div key={d.toISOString()} className={same(d,new Date(2026,7,24))?"today":""} onClick={()=>{setCursor(d);setMode("Dan")}}><header><b>{d.toLocaleDateString("sr-Latn-RS",{weekday:"short"})}</b><span>{d.getDate()}</span></header><section>{events.filter(b=>same(b.date,d)).map(eventButton)}{!events.some(b=>same(b.date,d))&&<small>Slobodan dan</small>}</section></div>)}</section>:<section className="panel day-calendar"><div className="day-hours">{Array.from({length:12},(_,i)=><span key={i}>{String(i+8).padStart(2,"0")}:00</span>)}</div><div className="day-agenda">{events.filter(b=>same(b.date,cursor)).map(eventButton)}{!events.some(b=>same(b.date,cursor))&&<div className="calendar-empty"><b>Nema rezervacija ovog dana</b><span>Kliknite ispod da kreirate novu rezervaciju.</span></div>}<button className="add-calendar-event" onClick={newReservation}>+ Dodaj rezervaciju za ovaj dan</button></div></section>}<div className="calendar-legend"><button onClick={()=>setStatus("Aktivna")}><Badge s="Aktivna"/></button><button onClick={()=>setStatus("Potvrđena")}><Badge s="Potvrđena"/></button><button onClick={()=>setStatus("Povrat danas")}><Badge s="Povrat danas"/></button><button onClick={()=>setStatus("Svi statusi")}>Prikaži sve</button></div></>}
const demoClients:C[]=[];
function Clients({addTrigger=0}:{addTrigger?:number}){const[q,setQ]=useState("");const{deleted,remove}=useSoftDelete("clients");const[status,setStatus]=useState("Svi statusi");const[city,setCity]=useState("Svi gradovi");const[more,setMore]=useState(false);const[sortValue,setSortValue]=useState(false);const[added,setAdded]=useState<C[]>([]);const[selected,setSelected]=useState<C|null>(null);const[showAdd,setShowAdd]=useState(addTrigger>0);const[loading,setLoading]=useState(true);const load=()=>{setLoading(true);fetch("/api/clients").then(r=>r.ok?r.json():Promise.reject()).then(data=>setAdded(data.clients||[])).catch(()=>{}).finally(()=>setLoading(false))};useEffect(()=>{load()},[]);useEffect(()=>{if(addTrigger>0)setShowAdd(true)},[addTrigger]);const all=[...added,...demoClients].filter(c=>!deleted.has(c.email)).filter((c,i,a)=>a.findIndex(x=>x.email===c.email)===i);const shown=all.filter(c=>(c.name+c.email+c.phone+c.city).toLowerCase().includes(q.toLowerCase())&&(status==="Svi statusi"||c.status===status)&&(city==="Svi gradovi"||c.city===city)).sort((a,b)=>sortValue?b.value-a.value:0);const clear=()=>{setQ("");setStatus("Svi statusi");setCity("Svi gradovi");setSortValue(false)};const totalClientValue=all.reduce((sum,c)=>sum+c.value,0);const clientKpis=[["Ukupno klijenata",String(all.length),"u centralnoj bazi","uživo","blue"],["Aktivni",String(all.filter(c=>c.status==="Aktivan").length),"aktivnih naloga","uživo","green"],["Sa rezervacijama",String(all.filter(c=>c.reservations>0).length),"ostvarili najam","uživo","violet"],["Prosečna vrednost",all.length?Math.round(totalClientValue/all.length).toLocaleString("sr-RS")+" RSD":"0 RSD","po klijentu","uživo","cyan"],["Loyalty članovi",String(all.filter(c=>c.status==="VIP").length),"VIP klijenata","uživo","amber"],["Ukupna vrednost",totalClientValue.toLocaleString("sr-RS")+" RSD","svi klijenti","uživo","green"]];return <><Head title="Klijenti" sub="Baza klijenata, dokumenta i istorija najma." action="Novi klijent" onAction={()=>setShowAdd(true)}/><Kpis items={clientKpis} actions={[clear,()=>setStatus("Aktivan"),()=>{setStatus("Svi statusi");setAdded(x=>x)},()=>{setStatus("Svi statusi");setSortValue(true)},()=>setStatus("VIP"),()=>{setStatus("Svi statusi");setSortValue(true)}]}/><section className="panel table-panel"><div className="toolbar"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Ime, email, telefon ili grad..."/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Aktivan</option><option>VIP</option><option>Na čekanju</option><option>Neaktivan</option></select><button className={more?"filter-active":""} onClick={()=>setMore(x=>!x)}>Više filtera ☷</button></div>{more&&<div className="advanced-filters"><label>Grad<select value={city} onChange={e=>setCity(e.target.value)}><option>Svi gradovi</option>{[...new Set(all.map(c=>c.city))].map(x=><option key={x}>{x}</option>)}</select></label><label><input type="checkbox" checked={sortValue} onChange={e=>setSortValue(e.target.checked)}/> Najvredniji klijenti prvo</label><button onClick={clear}>Očisti filtere</button></div>}<div className="active-filter-note">Prikazano {shown.length} od {all.length} klijenata</div><div className="table-scroll"><table><thead><tr><th>KLIJENT</th><th>GRAD</th><th>TELEFON</th><th>REZERVACIJE</th><th>UKUPNA VREDNOST</th><th>STATUS</th><th/></tr></thead><tbody>{shown.map(c=><tr key={c.email} onClick={()=>setSelected(c)}><td><div className="person"><span>{c.name.split(" ").map(x=>x[0]).join("")}</span><div><strong>{c.name}</strong><small>{c.email}</small></div></div></td><td>{c.city}</td><td>{c.phone}</td><td><strong>{c.reservations}</strong></td><td><strong>{c.value.toLocaleString("sr-RS")} RSD</strong></td><td><Badge s={c.status}/></td><td><RowMenu label={c.name} onOpen={()=>setSelected(c)} onDelete={()=>{void remove(c.email,c.name)}}/></td></tr>)}</tbody></table>{!loading&&!shown.length&&<div className="empty-table">Nema klijenata koji odgovaraju izabranim filterima.</div>}{loading&&<div className="vehicle-loading">Učitavanje sačuvanih klijenata…</div>}</div></section>{showAdd&&<ClientForm close={()=>setShowAdd(false)} saved={c=>{setAdded(x=>[c,...x]);setShowAdd(false)}}/>}{selected&&<ClientPanel client={selected} close={()=>setSelected(null)} saved={c=>{setAdded(x=>[c,...x.filter(y=>y.email!==selected.email)]);setSelected(c)}}/>}</>}
function ClientForm({close,saved}:{close:()=>void;saved:(c:C)=>void}){const[form,setForm]=useState<C>({name:"",email:"",city:"Beograd",phone:"",reservations:0,value:0,status:"Aktivan",notes:""});const[saving,setSaving]=useState(false);const[error,setError]=useState("");const set=(k:keyof C,v:string|number)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setError("");const name=form.name.trim();const email=form.email.trim().toLowerCase();const phone=form.phone.trim();if(name.length<3||!name.includes(" ")){setError("Unesite ime i prezime klijenta.");return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)){setError("Unesite ispravnu email adresu.");return}const phoneDigits=phone.replace(/\D/g,"");if(phoneDigits.length<8||phoneDigits.length>15){setError("Broj telefona mora imati između 8 i 15 cifara.");return}setSaving(true);try{const r=await fetch("/api/clients",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,name,email,phone})});const data=await r.json();if(!r.ok)throw new Error(data.error||"Klijent nije sačuvan.");saved(data.client)}catch(e){setError(e instanceof Error?e.message:"Klijent nije sačuvan.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>NOVI KLIJENT</small><h2>Dodaj klijenta</h2><p className="drawer-intro">Podaci će biti trajno sačuvani u bazi klijenata.</p><form onSubmit={submit}><label>Ime i prezime *<input required value={form.name} onChange={e=>set("name",e.target.value)} placeholder="Petar Petrović"/></label><div className="add-form-grid"><label>Email *<input required type="email" value={form.email} onChange={e=>set("email",e.target.value)} placeholder="petar@email.com"/></label><label>Telefon *<input required type="tel" inputMode="tel" autoComplete="tel" maxLength={24} value={form.phone} onChange={e=>set("phone",formatSerbianPhone(e.target.value))} placeholder="+381 64 123 4567"/></label><label>Grad *<select value={form.city} onChange={e=>set("city",e.target.value)}><option>Beograd</option><option>Novi Sad</option><option>Niš</option><option>Kragujevac</option><option>Subotica</option></select></label><label>Status<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Aktivan</option><option>VIP</option><option>Na čekanju</option><option>Neaktivan</option></select></label></div><label>Napomena<textarea value={form.notes} onChange={e=>set("notes",e.target.value)} placeholder="Preferencije i važne informacije..."/></label>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Dodaj klijenta"}</button></div></form></aside></div>}
function ClientPanel({client,close,saved}:{client:C;close:()=>void;saved:(c:C)=>void}){const[tab,setTab]=useState("Pregled");const[edit,setEdit]=useState(false);const[form,setForm]=useState(client);const[saving,setSaving]=useState(false);const[error,setError]=useState("");const set=(k:keyof C,v:string)=>setForm(f=>({...f,[k]:v}));const save=async()=>{setSaving(true);setError("");try{const r=await fetch("/api/clients",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,originalEmail:client.email})});const data=await r.json();if(!r.ok)throw new Error(data.error||"Izmene nisu sačuvane.");saved(data.client);setEdit(false)}catch(e){setError(e instanceof Error?e.message:"Izmene nisu sačuvane.")}finally{setSaving(false)}};const download=(name:string)=>{const url=URL.createObjectURL(new Blob([`DriveNode Fleet Manager\n${name}\nKlijent: ${form.name}\nEmail: ${form.email}\nTelefon: ${form.phone}\nStatus: ${form.status}`],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=`${name.replace(/\s/g,"_")}_${form.name.replace(/\s/g,"_")}.txt`;a.click();URL.revokeObjectURL(url)};return <div className="drawer-wrap" onClick={close}><aside className="drawer client-panel" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>KARTICA KLIJENTA</small><div className="client-hero"><span>{form.name.split(" ").map(x=>x[0]).join("")}</span><div><h2>{form.name}</h2><Badge s={form.status}/></div></div><div className="client-tabs">{["Pregled","Rezervacije","Dokumenta","Napomene"].map(x=><button key={x} className={tab===x?"active":""} onClick={()=>setTab(x)}>{x}</button>)}</div>{tab==="Pregled"&&(edit?<div className="client-edit"><label>Ime i prezime<input value={form.name} onChange={e=>set("name",e.target.value)}/></label><label>Email<input type="email" value={form.email} onChange={e=>set("email",e.target.value)}/></label><label>Telefon<input value={form.phone} onChange={e=>set("phone",formatSerbianPhone(e.target.value))}/></label><label>Grad<input value={form.city} onChange={e=>set("city",e.target.value)}/></label><label>Status<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Aktivan</option><option>VIP</option><option>Na čekanju</option><option>Neaktivan</option></select></label>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button className="outline" onClick={()=>setEdit(false)}>Otkaži</button><button className="primary" onClick={save} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj"}</button></div></div>:<><div className="client-contact">{[["Email",form.email],["Telefon",form.phone],["Grad",form.city],["Broj rezervacija",String(form.reservations)],["Ukupna vrednost",`${form.value.toLocaleString("sr-RS")} RSD`]].map(x=><div key={x[0]}><small>{x[0]}</small><b>{x[1]}</b></div>)}</div><button className="primary drawer-action" onClick={()=>setEdit(true)}>Uredi klijenta</button></>)}{tab==="Rezervacije"&&<div className="client-records">{bookings.filter(b=>b.client===form.name).map(b=><button key={b.id}><div><b>{b.id} • {b.vehicle}</b><small>{b.from} — {b.to}</small></div><Badge s={b.status}/></button>)}{!bookings.some(b=>b.client===form.name)&&<div className="empty-table">Klijent još nema rezervacija.</div>}</div>}{tab==="Dokumenta"&&<div className="client-records"><div className="empty-table">Klijent nema dodatih dokumenata.</div></div>}{tab==="Napomene"&&<div className="client-notes"><textarea value={form.notes} onChange={e=>set("notes",e.target.value)} placeholder="Dodajte napomenu o klijentu..."/><button className="primary" onClick={save} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj napomenu"}</button>{error&&<div className="form-error">{error}</div>}</div>}</aside></div>}
function SimpleTable({headers,rows}:{headers:string[];rows:string[][]}){return <section className="panel table-panel"><div className="table-scroll"><table><thead><tr>{headers.map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((x,j)=><td key={j}>{j===0?<strong>{x}</strong>:j===r.length-1?<Badge s={x}/>:x}</td>)}</tr>)}</tbody></table></div></section>}
const demoServices:S[]=[];
function Services(){const[q,setQ]=useState("");const{deleted,remove}=useSoftDelete("services");const[status,setStatus]=useState("Svi statusi");const[type,setType]=useState("Svi tipovi");const[more,setMore]=useState(false);const[sortCost,setSortCost]=useState(false);const[added,setAdded]=useState<S[]>([]);const[selected,setSelected]=useState<S|null>(null);const[showAdd,setShowAdd]=useState(false);const[loading,setLoading]=useState(true);const load=()=>{setLoading(true);fetch("/api/services").then(r=>r.ok?r.json():Promise.reject()).then(data=>setAdded(data.services||[])).catch(()=>{}).finally(()=>setLoading(false))};useEffect(()=>{load()},[]);const all=[...added,...demoServices].filter(s=>!deleted.has(s.code)).filter((s,i,a)=>a.findIndex(x=>x.code===s.code)===i);const shown=all.filter(s=>(s.vehicle+s.plate+s.type+s.workshop+s.code).toLowerCase().includes(q.toLowerCase())&&(status==="Svi statusi"||s.status===status)&&(type==="Svi tipovi"||s.type===type)).sort((a,b)=>sortCost?b.cost-a.cost:a.dueDate.localeCompare(b.dueDate));const reset=()=>{setQ("");setStatus("Svi statusi");setType("Svi tipovi");setSortCost(false)};const serviceCost=all.reduce((sum,s)=>sum+s.cost,0);const completed=all.filter(s=>s.status==="Završeno").length;const serviceKpis=[["Servis uskoro",String(all.filter(s=>s.status==="Uskoro"||s.status==="Planirano").length),"planiranih obaveza","uživo","red"],["Registracija",String(all.filter(s=>s.type==="Registracija").length),"evidentiranih rokova","uživo","amber"],["Na servisu",String(all.filter(s=>s.status==="U toku").length),"radova u toku","uživo","blue"],["Troškovi",serviceCost.toLocaleString("sr-RS")+" RSD","svih servisnih zapisa","uživo","violet"],["Završeno",String(completed),"servisnih radova","uživo","green"],["Uredno održavanje",all.length?Math.round(completed/all.length*100)+"%":"0%","završenih obaveza","uživo","cyan"]];return <><Head title="Servisi i registracije" sub="Održavanje, registracije i rokovi cele flote." action="Novi servis" onAction={()=>setShowAdd(true)}/><Kpis items={serviceKpis} actions={[()=>setStatus("Uskoro"),()=>{setStatus("Svi statusi");setType("Registracija")},()=>setStatus("U toku"),()=>{setStatus("Svi statusi");setSortCost(true)},()=>setStatus("Završeno"),reset]}/><section className="panel table-panel"><div className="toolbar"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Vozilo, tablice, tip ili radionica..."/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Planirano</option><option>Uskoro</option><option>U toku</option><option>Završeno</option><option>Otkazano</option></select><button className={more?"filter-active":""} onClick={()=>setMore(x=>!x)}>Više filtera ☷</button></div>{more&&<div className="advanced-filters"><label>Tip<select value={type} onChange={e=>setType(e.target.value)}><option>Svi tipovi</option><option>Redovan servis</option><option>Veliki servis</option><option>Registracija</option><option>Tehnički pregled</option><option>Pneumatici</option><option>Popravka</option></select></label><label><input type="checkbox" checked={sortCost} onChange={e=>setSortCost(e.target.checked)}/> Najveći trošak prvo</label><button onClick={reset}>Očisti filtere</button></div>}<div className="active-filter-note">Prikazano {shown.length} od {all.length} zapisa</div><div className="table-scroll"><table><thead><tr><th>REFERENCA</th><th>VOZILO</th><th>TIP</th><th>ROK</th><th>RADIONICA</th><th>PROCENA</th><th>STATUS</th><th/></tr></thead><tbody>{shown.map(s=><tr key={s.code} onClick={()=>setSelected(s)}><td><strong className="link">{s.code}</strong></td><td><strong>{s.vehicle}</strong><small>{s.plate} • {s.mileage.toLocaleString("sr-RS")} km</small></td><td>{s.type}</td><td><strong>{new Date(`${s.dueDate}T12:00`).toLocaleDateString("sr-Latn-RS")}</strong></td><td>{s.workshop||"Nije određena"}</td><td><strong>{s.cost?s.cost.toLocaleString("sr-RS")+" RSD":"Ponuda"}</strong></td><td><Badge s={s.status}/></td><td><RowMenu label={s.code} onOpen={()=>setSelected(s)} onDelete={()=>{void remove(s.code,s.code)}}/></td></tr>)}</tbody></table>{!loading&&!shown.length&&<div className="empty-table">Nema zapisa koji odgovaraju izabranim filterima.</div>}{loading&&<div className="vehicle-loading">Učitavanje servisnih zapisa…</div>}</div></section>{showAdd&&<ServiceForm close={()=>setShowAdd(false)} saved={s=>{setAdded(x=>[s,...x]);setShowAdd(false)}}/>}{selected&&<ServicePanel service={selected} close={()=>setSelected(null)} saved={s=>{setAdded(x=>[s,...x.filter(y=>y.code!==selected.code)]);setSelected(s)}}/>}</>}
function ServiceForm({close,saved}:{close:()=>void;saved:(s:S)=>void}){const[vehicleOptions,setVehicleOptions]=useState<V[]>([]);const[vehiclePlate,setVehiclePlate]=useState("");useEffect(()=>{fetch("/api/vehicles").then(r=>r.ok?r.json():Promise.reject()).then(d=>{const list=d.vehicles||[];setVehicleOptions(list);if(list[0])setVehiclePlate(list[0].plate)}).catch(()=>{})},[]);const vehicle=vehicleOptions.find(v=>v.plate===vehiclePlate);const[form,setForm]=useState({type:"Redovan servis",dueDate:"",mileage:"",cost:"",workshop:"",status:"Planirano",notes:""});const[saving,setSaving]=useState(false);const[error,setError]=useState("");const set=(k:string,v:string)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setError("");if(!vehicle){setError("Prvo dodajte vozilo.");return}setSaving(true);try{const r=await fetch("/api/services",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,vehicle:vehicle.name,plate:vehicle.plate,mileage:Number(form.mileage),cost:Number(form.cost)})});const data=await r.json();if(!r.ok)throw new Error(data.error||"Zapis nije sačuvan.");saved(data.service)}catch(e){setError(e instanceof Error?e.message:"Zapis nije sačuvan.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>NOVI SERVISNI ZAPIS</small><h2>Zakaži servis ili registraciju</h2><form onSubmit={submit}><label>Vozilo *<select value={vehiclePlate} onChange={e=>setVehiclePlate(e.target.value)}><option value="">Izaberite vozilo</option>{vehicleOptions.map(v=><option value={v.plate} key={v.plate}>{v.name} • {v.plate}</option>)}</select></label><div className="add-form-grid"><label>Tip *<select value={form.type} onChange={e=>set("type",e.target.value)}><option>Redovan servis</option><option>Veliki servis</option><option>Registracija</option><option>Tehnički pregled</option><option>Pneumatici</option><option>Popravka</option></select></label><label>Datum *<input required type="date" value={form.dueDate} onChange={e=>set("dueDate",e.target.value)}/></label><label>Kilometraža<input type="number" min="0" value={form.mileage} onChange={e=>set("mileage",e.target.value)}/></label><label>Procena troška (RSD)<input type="number" min="0" step="100" value={form.cost} onChange={e=>set("cost",e.target.value)}/></label><label>Radionica<input value={form.workshop} onChange={e=>set("workshop",e.target.value)} placeholder="Auto Centar Beograd"/></label><label>Status<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Planirano</option><option>Uskoro</option><option>U toku</option><option>Završeno</option></select></label></div><label>Napomena<textarea value={form.notes} onChange={e=>set("notes",e.target.value)} placeholder="Potrebni delovi, opis radova..."/></label>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Sačuvaj zapis"}</button></div></form></aside></div>}
function ServicePanel({service,close,saved}:{service:S;close:()=>void;saved:(s:S)=>void}){const[form,setForm]=useState(service);const[saving,setSaving]=useState(false);const[error,setError]=useState("");const set=(k:keyof S,v:string|number)=>setForm(f=>({...f,[k]:v}));const save=async(status?:string)=>{setSaving(true);setError("");try{const next={...form,status:status||form.status};const r=await fetch("/api/services",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(next)});const data=await r.json();if(!r.ok)throw new Error(data.error||"Izmene nisu sačuvane.");setForm(data.service);saved(data.service)}catch(e){setError(e instanceof Error?e.message:"Izmene nisu sačuvane.")}finally{setSaving(false)}};const download=()=>{const url=URL.createObjectURL(new Blob([`DriveNode Fleet Manager\nServisni nalog ${form.code}\nVozilo: ${form.vehicle} • ${form.plate}\nTip: ${form.type}\nDatum: ${form.dueDate}\nRadionica: ${form.workshop}\nTrošak: ${form.cost} RSD\nStatus: ${form.status}\nNapomena: ${form.notes}`],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=`Servisni_nalog_${form.code}.txt`;a.click();URL.revokeObjectURL(url)};return <div className="drawer-wrap" onClick={close}><aside className="drawer service-panel" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>SERVISNI ZAPIS {form.code}</small><h2>{form.vehicle}</h2><Badge s={form.status}/><div className="service-summary"><div><small>Tablice</small><b>{form.plate}</b></div><div><small>Tip</small><b>{form.type}</b></div><div><small>Rok</small><b>{new Date(`${form.dueDate}T12:00`).toLocaleDateString("sr-Latn-RS")}</b></div><div><small>Radionica</small><b>{form.workshop||"Nije određena"}</b></div></div><div className="service-edit"><label>Status<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Planirano</option><option>Uskoro</option><option>U toku</option><option>Završeno</option><option>Otkazano</option></select></label><label>Trošak (RSD)<input type="number" min="0" value={form.cost} onChange={e=>set("cost",Number(e.target.value))}/></label><label>Datum<input type="date" value={form.dueDate} onChange={e=>set("dueDate",e.target.value)}/></label><label>Kilometraža<input type="number" min="0" value={form.mileage} onChange={e=>set("mileage",Number(e.target.value))}/></label><label className="full">Radionica<input value={form.workshop} onChange={e=>set("workshop",e.target.value)}/></label><label className="full">Napomena<textarea value={form.notes} onChange={e=>set("notes",e.target.value)}/></label></div>{error&&<div className="form-error">{error}</div>}<button className="doc-row" onClick={download}>□ Preuzmi servisni nalog <span>TXT ↓</span></button><div className="service-actions"><button className="outline" onClick={()=>save("Završeno")} disabled={saving}>✓ Označi završeno</button><button className="primary" onClick={()=>save()} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj izmene"}</button></div></aside></div>}
const demoFinance:F[]=[];
function Finance(){const[q,setQ]=useState("");const{deleted,remove}=useSoftDelete("transactions");const[kind,setKind]=useState("Sve transakcije");const[status,setStatus]=useState("Svi statusi");const[location,setLocation]=useState("Sve lokacije");const[period,setPeriod]=useState(6);const[added,setAdded]=useState<F[]>([]);const[selected,setSelected]=useState<F|null>(null);const[showAdd,setShowAdd]=useState(false);const load=()=>fetch("/api/transactions").then(r=>r.ok?r.json():Promise.reject()).then(d=>setAdded(d.transactions||[])).catch(()=>{});useEffect(()=>{load()},[]);const all=[...added,...demoFinance].filter(x=>!deleted.has(x.reference)).filter((x,i,a)=>a.findIndex(y=>y.reference===x.reference)===i);const shown=all.filter(x=>(x.reference+x.description+x.category).toLowerCase().includes(q.toLowerCase())&&(kind==="Sve transakcije"||x.kind===kind)&&(status==="Svi statusi"||x.status===status)&&(location==="Sve lokacije"||x.location===location));const reset=()=>{setQ("");setKind("Sve transakcije");setStatus("Svi statusi");setLocation("Sve lokacije")};const paid=all.filter(x=>x.status==="Plaćeno");const income=paid.filter(x=>x.kind==="Prihod").reduce((sum,x)=>sum+x.amount,0);const expenses=paid.filter(x=>x.kind==="Rashod").reduce((sum,x)=>sum+x.amount,0);const pending=all.filter(x=>x.status==="Na čekanju").reduce((sum,x)=>sum+x.amount,0);const rentals=all.filter(x=>x.kind==="Prihod"&&x.category.toLowerCase().includes("najam"));const financeKpis=[["Ukupan prihod",income.toLocaleString("sr-RS")+" RSD","plaćene transakcije","uživo","green"],["Broj prihoda",String(paid.filter(x=>x.kind==="Prihod").length),"evidentirane uplate","uživo","blue"],["Ukupni rashodi",expenses.toLocaleString("sr-RS")+" RSD","plaćeni rashodi","uživo","red"],["Neto profit",(income-expenses).toLocaleString("sr-RS")+" RSD","prihod minus rashodi","uživo","violet"],["Potraživanja",pending.toLocaleString("sr-RS")+" RSD","transakcije na čekanju","uživo","amber"],["Prosečan najam",rentals.length?Math.round(rentals.reduce((sum,x)=>sum+x.amount,0)/rentals.length).toLocaleString("sr-RS")+" RSD":"0 RSD","po transakciji najma","uživo","cyan"]];return <><Head title="Finansije" sub="Prihodi, rashodi i profitabilnost poslovanja." action="Nova transakcija" onAction={()=>setShowAdd(true)}/><Kpis items={financeKpis} actions={[()=>setKind("Prihod"),()=>setKind("Prihod"),()=>setKind("Rashod"),reset,()=>setStatus("Na čekanju"),()=>{setKind("Prihod");setQ("Najam")}]}/><div className="finance-grid"><section className="panel finance-chart"><div className="panel-head"><div><h2>Prihodi i rashodi</h2><p>Poslednjih {period} meseci</p></div><button onClick={()=>setPeriod(p=>p===6?12:3)}>{period} meseci ⌄</button></div><div className="bar-chart">{(period===3?[[0,0],[0,0],[0,0]]:period===6?Array(6).fill([0,0]):Array(12).fill([0,0])).map((b,i)=><div key={i}><i style={{height:b[0]*1.4}}/><em style={{height:b[1]*1.4}}/><span>{i+1}</span></div>)}</div></section><section className="panel donut-panel clickable-chart" onClick={()=>setLocation(l=>l==="Beograd"?"Novi Sad":l==="Novi Sad"?"Niš":"Beograd")}><h2>Prihod po lokaciji</h2><div className="donut"><b>0<small>RSD</small></b></div><p>Nema podataka po lokaciji</p><small>Kliknite za filter lokacije</small></section></div><section className="panel table-panel"><div className="finance-filters"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Referenca, opis ili kategorija..."/></div><select value={kind} onChange={e=>setKind(e.target.value)}><option>Sve transakcije</option><option>Prihod</option><option>Rashod</option></select><select value={status} onChange={e=>setStatus(e.target.value)}><option>Svi statusi</option><option>Plaćeno</option><option>Na čekanju</option><option>Stornirano</option></select><select value={location} onChange={e=>setLocation(e.target.value)}><option>Sve lokacije</option><option>Beograd</option><option>Novi Sad</option><option>Niš</option></select><button onClick={reset}>Očisti</button></div><div className="active-filter-note">Prikazano {shown.length} od {all.length} transakcija</div><div className="table-scroll"><table><thead><tr><th>DATUM</th><th>REFERENCA</th><th>OPIS</th><th>KATEGORIJA</th><th>LOKACIJA</th><th>IZNOS</th><th>STATUS</th><th/></tr></thead><tbody>{shown.map(x=><tr key={x.reference} onClick={()=>setSelected(x)}><td>{new Date(`${x.date}T12:00`).toLocaleDateString("sr-Latn-RS")}</td><td><strong className="link">{x.reference}</strong></td><td>{x.description}</td><td>{x.category}</td><td>{x.location}</td><td><strong className={x.kind==="Rashod"?"expense":"income"}>{x.kind==="Rashod"?"−":"+"}{x.amount.toLocaleString("sr-RS")} RSD</strong></td><td><Badge s={x.status}/></td><td><RowMenu label={x.reference} onOpen={()=>setSelected(x)} onDelete={()=>{void remove(x.reference,`transakciju `)}}/></td></tr>)}</tbody></table>{!shown.length&&<div className="empty-table">Nema transakcija za izabrane filtere.</div>}</div></section>{showAdd&&<TransactionForm close={()=>setShowAdd(false)} saved={x=>{setAdded(a=>[x,...a]);setShowAdd(false)}}/>}{selected&&<TransactionPanel item={selected} close={()=>setSelected(null)} saved={(ref,s)=>{setAdded(a=>a.map(x=>x.reference===ref?{...x,status:s}:x));setSelected(x=>x?{...x,status:s}:x)}}/>}</>}
function TransactionForm({close,saved}:{close:()=>void;saved:(x:F)=>void}){const[form,setForm]=useState({description:"",category:"Najam",kind:"Prihod",amount:"",date:"2026-08-25",location:"Beograd",status:"Plaćeno",paymentMethod:"Kartica",notes:""});const[saving,setSaving]=useState(false);const[error,setError]=useState("");const set=(k:string,v:string)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);try{const r=await fetch("/api/transactions",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,amount:Number(form.amount)})});const d=await r.json();if(!r.ok)throw new Error(d.error);saved(d.transaction)}catch(e){setError(e instanceof Error?e.message:"Transakcija nije sačuvana.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>NOVA TRANSAKCIJA</small><h2>Dodaj prihod ili rashod</h2><form onSubmit={submit}><label>Opis *<input required value={form.description} onChange={e=>set("description",e.target.value)}/></label><div className="add-form-grid"><label>Vrsta<select value={form.kind} onChange={e=>set("kind",e.target.value)}><option>Prihod</option><option>Rashod</option></select></label><label>Kategorija<select value={form.category} onChange={e=>set("category",e.target.value)}><option>Najam</option><option>Depozit</option><option>Servis</option><option>Registracija</option><option>Osiguranje</option><option>Ostalo</option></select></label><label>Iznos (RSD) *<input required type="number" min="1" value={form.amount} onChange={e=>set("amount",e.target.value)}/></label><label>Datum<input type="date" value={form.date} onChange={e=>set("date",e.target.value)}/></label><label>Lokacija<select value={form.location} onChange={e=>set("location",e.target.value)}><option>Beograd</option><option>Novi Sad</option><option>Niš</option></select></label><label>Plaćanje<select value={form.paymentMethod} onChange={e=>set("paymentMethod",e.target.value)}><option>Kartica</option><option>Gotovina</option><option>Prenos</option></select></label><label>Status<select value={form.status} onChange={e=>set("status",e.target.value)}><option>Plaćeno</option><option>Na čekanju</option></select></label></div><label>Napomena<textarea value={form.notes} onChange={e=>set("notes",e.target.value)}/></label>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Čuvanje…":"Sačuvaj transakciju"}</button></div></form></aside></div>}
function TransactionPanel({item,close,saved}:{item:F;close:()=>void;saved:(r:string,s:string)=>void}){const[status,setStatus]=useState(item.status);const[saving,setSaving]=useState(false);const save=async()=>{setSaving(true);const r=await fetch("/api/transactions",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({reference:item.reference,status})});if(r.ok)saved(item.reference,status);setSaving(false)};const download=()=>{const u=URL.createObjectURL(new Blob([`DriveNode Fleet Manager\nPotvrda ${item.reference}\n${item.description}\n${item.kind}: ${item.amount} RSD\nDatum: ${item.date}\nNačin plaćanja: ${item.paymentMethod}\nStatus: ${status}`],{type:"text/plain;charset=utf-8"}));const a=document.createElement("a");a.href=u;a.download=`Potvrda_${item.reference}.txt`;a.click();URL.revokeObjectURL(u)};return <div className="drawer-wrap" onClick={close}><aside className="drawer" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>TRANSAKCIJA {item.reference}</small><h2>{item.description}</h2><Badge s={status}/><div className="transaction-amount"><small>{item.kind}</small><b>{item.kind==="Rashod"?"−":"+"}{item.amount.toLocaleString("sr-RS")} RSD</b></div><div className="client-contact">{[["Datum",new Date(`${item.date}T12:00`).toLocaleDateString("sr-Latn-RS")],["Kategorija",item.category],["Lokacija",item.location],["Način plaćanja",item.paymentMethod],["Napomena",item.notes||"Nema napomene"]].map(x=><div key={x[0]}><small>{x[0]}</small><b>{x[1]}</b></div>)}</div><button className="doc-row" onClick={download}>□ Preuzmi potvrdu <span>TXT ↓</span></button><label className="status-control">Promeni status<select value={status} onChange={e=>setStatus(e.target.value)}><option>Plaćeno</option><option>Na čekanju</option><option>Stornirano</option></select></label><button className="primary drawer-action" onClick={save} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj status"}</button></aside></div>}
const demoDocs:D[]=[];
function Documents(){const[q,setQ]=useState("");const{deleted,remove}=useSoftDelete("documents");const[folder,setFolder]=useState("Sve fascikle");const[added,setAdded]=useState<D[]>([]);const[selected,setSelected]=useState<D|null>(null);const[upload,setUpload]=useState(false);const load=()=>fetch("/api/documents").then(r=>r.ok?r.json():Promise.reject()).then(d=>setAdded(d.documents||[])).catch(()=>{});useEffect(()=>{load()},[]);const all=[...added,...demoDocs].filter(d=>!deleted.has(d.storageKey));const shown=all.filter(d=>(d.name+d.linkedTo+d.uploadedBy).toLowerCase().includes(q.toLowerCase())&&(folder==="Sve fascikle"||d.folder===folder));const total=all.reduce((s,d)=>s+d.size,0);return <><Head title="Dokumentacija" sub="Sva dokumenta organizovana i dostupna na jednom mestu." action="Otpremi dokument" onAction={()=>setUpload(true)}/><div className="doc-stats"><button onClick={()=>setFolder("Sve fascikle")}><b>{all.length}</b><small>Ukupno dokumenata</small></button><button onClick={()=>setFolder("Sve fascikle")}><b>{(total/1024/1024).toFixed(1)} MB</b><small>Iskorišćeno</small></button><button onClick={()=>setFolder("Sve fascikle")}><b>{all.filter(d=>d.expiresAt).length}</b><small>Sa rokom važenja</small></button></div><h2 className="section-title">Fascikle</h2><div className="folder-grid">{["Vozila","Klijenti","Ugovori","Registracije","Osiguranja"].map(f=><button className={`folder ${folder===f?"active":""}`} key={f} onClick={()=>setFolder(f)}><span>□</span><b>{f}</b><small>{all.filter(d=>d.folder===f).length} dokumenta</small><i>›</i></button>)}</div><section className="panel table-panel"><div className="finance-filters"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Naziv, povezani zapis ili autor..."/></div><select value={folder} onChange={e=>setFolder(e.target.value)}><option>Sve fascikle</option><option>Vozila</option><option>Klijenti</option><option>Ugovori</option><option>Registracije</option><option>Osiguranja</option><option>Ostalo</option></select><button onClick={()=>{setQ("");setFolder("Sve fascikle")}}>Očisti</button></div><div className="active-filter-note">Prikazano {shown.length} od {all.length} dokumenata</div><div className="table-scroll"><table><thead><tr><th>NAZIV</th><th>FASCIKLA</th><th>POVEZANO SA</th><th>VELIČINA</th><th>DODAO</th><th>DATUM</th><th/></tr></thead><tbody>{shown.map(d=><tr key={d.storageKey} onClick={()=>setSelected(d)}><td><strong className="link">□ {d.name}</strong><small>{d.mimeType}</small></td><td>{d.folder}</td><td>{d.linkedTo||"—"}</td><td>{d.size<1048576?`${Math.round(d.size/1024)} KB`:`${(d.size/1048576).toFixed(1)} MB`}</td><td>{d.uploadedBy}</td><td>{new Date(`${d.createdAt.slice(0,10)}T12:00`).toLocaleDateString("sr-Latn-RS")}</td><td><RowMenu label={d.name} onOpen={()=>setSelected(d)} onDelete={()=>{void remove(d.storageKey,d.name)}}/></td></tr>)}</tbody></table>{!shown.length&&<div className="empty-table">Nema dokumenata u ovoj fascikli.</div>}</div></section>{upload&&<DocumentUpload close={()=>setUpload(false)} saved={d=>{setAdded(x=>[d,...x]);setUpload(false)}}/>}{selected&&<DocumentPanel doc={selected} close={()=>setSelected(null)} changed={d=>{setAdded(x=>[d,...x.filter(y=>y.id!==d.id)]);setSelected(d)}} deleted={d=>{setAdded(x=>x.filter(y=>y.id!==d.id));setSelected(null)}}/>}</>}
function DocumentUpload({close,saved,defaultFolder="Ugovori",defaultLinkedTo=""}:{close:()=>void;saved:(d:D)=>void;defaultFolder?:string;defaultLinkedTo?:string}){const[file,setFile]=useState<File|null>(null);const[folder,setFolder]=useState(defaultFolder);const[linkedTo,setLinkedTo]=useState(defaultLinkedTo);const[expiresAt,setExpiresAt]=useState("");const[saving,setSaving]=useState(false);const[error,setError]=useState("");const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!file)return;setSaving(true);const body=new FormData();body.append("file",file);body.append("folder",folder);body.append("linkedTo",linkedTo);body.append("expiresAt",expiresAt);try{const r=await fetch("/api/documents",{method:"POST",body});const d=await r.json();if(!r.ok)throw new Error(d.error);saved(d.document)}catch(e){setError(e instanceof Error?e.message:"Upload nije uspeo.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>OTPREMANJE DOKUMENTA</small><h2>Dodaj dokument</h2><form onSubmit={submit}><label className="upload-zone">Izaberite fajl do 10 MB<input required type="file" onChange={e=>setFile(e.target.files?.[0]||null)}/><b>{file?.name||"Kliknite za izbor fajla"}</b></label><div className="add-form-grid"><label>Fascikla<select value={folder} onChange={e=>setFolder(e.target.value)}><option>Vozila</option><option>Klijenti</option><option>Ugovori</option><option>Registracije</option><option>Osiguranja</option><option>Ostalo</option></select></label><label>Povezano sa<input value={linkedTo} onChange={e=>setLinkedTo(e.target.value)} placeholder="Vozilo, klijent ili rezervacija"/></label><label>Važi do<input type="date" value={expiresAt} onChange={e=>setExpiresAt(e.target.value)}/></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving||!file}>{saving?"Otpremanje…":"Otpremi dokument"}</button></div></form></aside></div>}
function DocumentPanel({doc,close,changed,deleted}:{doc:D;close:()=>void;changed:(d:D)=>void;deleted:(d:D)=>void}){const[form,setForm]=useState(doc);const[saving,setSaving]=useState(false);const isDemo=!doc.id;const download=()=>{if(doc.id){location.href=`/api/documents?download=${doc.id}`;return}const u=URL.createObjectURL(new Blob([`DriveNode demo dokument\n${doc.name}\nFascikla: ${doc.folder}\nPovezano sa: ${doc.linkedTo}`],{type:"text/plain"}));const a=document.createElement("a");a.href=u;a.download=doc.name+".txt";a.click();URL.revokeObjectURL(u)};const save=async()=>{if(isDemo){changed(form);return}setSaving(true);const r=await fetch("/api/documents",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(form)});if(r.ok)changed((await r.json()).document);setSaving(false)};const remove=async()=>{if(!confirm(`Obrisati dokument ${doc.name}?`))return;if(isDemo){deleted(doc);return}const r=await fetch(`/api/documents?id=${doc.id}`,{method:"DELETE"});if(r.ok)deleted(doc)};return <div className="drawer-wrap" onClick={close}><aside className="drawer" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>DOKUMENT</small><h2>{doc.name}</h2><div className="document-icon">□</div><div className="client-edit"><label>Naziv<input value={form.name} onChange={e=>setForm(x=>({...x,name:e.target.value}))}/></label><label>Fascikla<select value={form.folder} onChange={e=>setForm(x=>({...x,folder:e.target.value}))}><option>Vozila</option><option>Klijenti</option><option>Ugovori</option><option>Registracije</option><option>Osiguranja</option><option>Ostalo</option></select></label><label className="full">Povezano sa<input value={form.linkedTo} onChange={e=>setForm(x=>({...x,linkedTo:e.target.value}))}/></label><label>Važi do<input type="date" value={form.expiresAt||""} onChange={e=>setForm(x=>({...x,expiresAt:e.target.value}))}/></label></div><button className="primary drawer-action" onClick={download}>Preuzmi dokument</button><div className="document-actions"><button className="outline" onClick={remove}>Obriši</button><button className="primary" onClick={save} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj izmene"}</button></div></aside></div>}
function Reports(){const[period,setPeriod]=useState("Avgust 2026");const[location,setLocation]=useState("Sve poslovnice");const[metric,setMetric]=useState("Pregled");const[selected,setSelected]=useState<{title:string;value:string;detail:string}|null>(null);const[sort,setSort]=useState("Prihod");const utilization=[["Economy",0],["Compact",0],["Premium",0],["SUV",0],["Kombi",0]] as [string,number][];const profits=[0,0,0,0,0];const exportCsv=()=>{const rows=[["DNFM Izveštaj",period,location],["Vozilo","Tablice","Iskorišćenost","Prihod RSD"],...vehicles.slice(0,5).map((v,i)=>[v.name,v.plate,`${utilization[i][1]}%`,String(profits[i])])];const url=URL.createObjectURL(new Blob(["\ufeff"+rows.map(r=>r.map(x=>`\"${x}\"`).join(";")).join("\n")],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=`DNFM_izvestaj_${period.replace(/\s/g,"_")}.csv`;a.click();URL.revokeObjectURL(url)};const details=[{title:"Iskorišćenost flote",value:"0%",detail:"Nema podataka."},{title:"Prihod po vozilu",value:"0 RSD",detail:"Nema podataka."},{title:"Broj rezervacija",value:"0",detail:"Nema podataka."},{title:"Prosečno trajanje",value:"0 dana",detail:"Nema podataka."},{title:"Najprofitabilnije",value:"—",detail:"Nema podataka."},{title:"Ocena klijenata",value:"—",detail:"Nema recenzija."}];return <><div className="page-title report-head"><div><h1>Izveštaji</h1><small>Ključni pokazatelji za donošenje boljih poslovnih odluka.</small></div><div className="report-actions"><select value={period} onChange={e=>setPeriod(e.target.value)}><option>Avgust 2026</option><option>Jul 2026</option><option>Q3 2026</option><option>2026. godina</option></select><select value={location} onChange={e=>setLocation(e.target.value)}><option>Sve poslovnice</option><option>Beograd</option><option>Novi Sad</option><option>Niš</option></select><button className="outline" onClick={exportCsv}>Excel / CSV ↓</button><button className="primary" onClick={()=>window.print()}>PDF / Štampa</button></div></div><Kpis items={[["Iskorišćenost flote","0%","nema podataka","—","green"],["Prihod po vozilu","0 RSD","nema podataka","—","blue"],["Broj rezervacija","0","nema rezervacija","—","violet"],["Prosečno trajanje","0 dana","nema podataka","—","cyan"],["Najprofitabilnije","—","nema vozila","—","amber"],["Ocena klijenata","—","nema recenzija","—","green"]]} actions={details.map(d=>()=>{setMetric(d.title);setSelected(d)})}/><div className="report-filter-note"><b>{metric}</b><span>{period} • {location}</span><button onClick={()=>setMetric("Pregled")}>Resetuj pregled</button></div><div className="reports-grid"><section className="panel"><div className="panel-head"><div><h2>Iskorišćenost flote</h2><p>Kliknite na kategoriju za detalje</p></div><select value={sort} onChange={e=>setSort(e.target.value)}><option>Prihod</option><option>Iskorišćenost</option></select></div>{utilization.map(x=><button className="progress-row report-row" key={x[0]} onClick={()=>setSelected({title:x[0],value:`${x[1]}%`,detail:`Kategorija ${x[0]} ima ${x[1]}% iskorišćenosti u periodu ${period} za lokaciju ${location}.`})}><span>{x[0]}</span><i><em style={{width:`${x[1]}%`}}/></i><b>{x[1]}%</b></button>)}</section><section className="panel"><div className="panel-head"><div><h2>Najprofitabilnija vozila</h2><p>{sort} • {period}</p></div><button onClick={()=>setSort(s=>s==="Prihod"?"Iskorišćenost":"Prihod")}>Promeni rangiranje</button></div>{vehicles.slice(0,5).map((v,i)=><button className="ranking report-ranking" key={v.plate} onClick={()=>setSelected({title:v.name,value:`${profits[i].toLocaleString("sr-RS")} RSD`,detail:`${v.plate} • ${v.location}. Vozilo ima ${utilization[i][1]}% iskorišćenosti i ${v.status.toLowerCase()} status.`})}><b>0{i+1}</b><span className="car-thumb">▰</span><div><strong>{v.name}</strong><small>{v.plate}</small></div><em>{profits[i].toLocaleString("sr-RS")} RSD</em></button>)}</section></div><div className="report-bottom"><section className="panel trend-card"><div className="panel-head"><div><h2>Trend rezervacija</h2><p>Poslednjih 6 meseci</p></div></div><div className="mini-bars">{[0,0,0,0,0,0].map((x,i)=><button key={i} onClick={()=>setSelected({title:["Mar","Apr","Maj","Jun","Jul","Avg"][i],value:`${Math.round(x*3)} rezervacija`,detail:`Detaljan broj rezervacija za mesec ${["mart","april","maj","jun","jul","avgust"][i]} 2026.`})}><i style={{height:`${x}%`}}/><span>{["Mar","Apr","Maj","Jun","Jul","Avg"][i]}</span></button>)}</div></section><section className="panel rating-card"><h2>Zadovoljstvo klijenata</h2>{[5,4,3,2,1].map((x,i)=><button key={x} onClick={()=>setSelected({title:`${x} zvezdica`,value:`${[0,0,0,0,0][i]}%`,detail:`Udeo recenzija sa ocenom ${x} u ukupno 0 recenzija.`})}><span>{x} ★</span><i><em style={{width:`${[0,0,0,0,0][i]}%`}}/></i><b>{[0,0,0,0,0][i]}%</b></button>)}</section></div>{selected&&<ReportPanel item={selected} period={period} location={location} close={()=>setSelected(null)} exportCsv={exportCsv}/>}</>}
function ReportPanel({item,period,location,close,exportCsv}:{item:{title:string;value:string;detail:string};period:string;location:string;close:()=>void;exportCsv:()=>void}){return <div className="drawer-wrap" onClick={close}><aside className="drawer report-panel" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>DETALJ IZVEŠTAJA</small><h2>{item.title}</h2><div className="report-big-value">{item.value}</div><p>{item.detail}</p><div className="client-contact"><div><small>Period</small><b>{period}</b></div><div><small>Poslovnica</small><b>{location}</b></div><div><small>Poslednje ažuriranje</small><b>Danas, 10:30</b></div><div><small>Izvor</small><b>DNFM analitika</b></div></div><button className="outline drawer-action" onClick={exportCsv}>Preuzmi podatke (CSV)</button><button className="primary drawer-action" onClick={()=>window.print()}>Sačuvaj kao PDF / Štampaj</button></aside></div>}
const demoUsers:U[]=[];
function Users(){const[q,setQ]=useState("");const{deleted,remove}=useSoftDelete("users");const[role,setRole]=useState("Sve uloge");const[tab,setTab]=useState("Korisnici");const[added,setAdded]=useState<U[]>([]);const[selected,setSelected]=useState<U|null>(null);const[invite,setInvite]=useState(false);const load=()=>fetch("/api/users").then(r=>r.ok?r.json():Promise.reject()).then(d=>setAdded(d.users||[])).catch(()=>{});useEffect(()=>{load()},[]);const all=[...added,...demoUsers].filter(u=>!deleted.has(u.email)).filter((u,i,a)=>a.findIndex(x=>x.email===u.email)===i).map(u=>({...u,permissions:safePermissions(u.permissions)}));const shown=all.filter(u=>(u.name+u.email+u.branch).toLowerCase().includes(q.toLowerCase())&&(role==="Sve uloge"||u.role===role));return <><Head title="Korisnici i dozvole" sub="Upravljajte timom, ulogama i pristupom podacima." action="Pozovi korisnika" onAction={()=>setInvite(true)}/><div className="detail-tabs user-tabs">{["Korisnici","Uloge i dozvole","Aktivnosti"].map(x=><button key={x} className={tab===x?"active":""} onClick={()=>setTab(x)}>{x}</button>)}</div>{tab==="Korisnici"&&<section className="panel table-panel"><div className="finance-filters"><div className="table-search">⌕<input value={q} onChange={e=>setQ(e.target.value)} placeholder="Ime, email ili poslovnica..."/></div><select value={role} onChange={e=>setRole(e.target.value)}><option>Sve uloge</option><option>Administrator</option><option>Menadžer</option><option>Agent</option><option>Računovođa</option></select><button onClick={()=>{setQ("");setRole("Sve uloge")}}>Očisti</button></div><div className="active-filter-note">{shown.length} korisnika</div><div className="table-scroll"><table><thead><tr><th>KORISNIK</th><th>EMAIL</th><th>ULOGA</th><th>POSLOVNICA</th><th>POSLEDNJA AKTIVNOST</th><th>STATUS</th><th/></tr></thead><tbody>{shown.map(u=><tr key={u.email} onClick={()=>setSelected(u)}><td><div className="person"><span>{u.name.split(" ").map(x=>x[0]).join("")}</span><strong>{u.name}</strong></div></td><td>{u.email}</td><td>{u.role}</td><td>{u.branch}</td><td>{u.lastActive}</td><td><Badge s={u.status}/></td><td><RowMenu label={u.name} onOpen={()=>setSelected(u)} onDelete={()=>{void remove(u.email,u.name)}}/></td></tr>)}</tbody></table></div></section>}{tab==="Uloge i dozvole"&&<div className="role-grid">{[["Administrator","Potpun pristup",7],["Menadžer","Operativno upravljanje",5],["Agent","Rezervacije i klijenti",3],["Računovođa","Finansije i izveštaji",2]].map(r=><button key={r[0]} onClick={()=>{setRole(String(r[0]));setTab("Korisnici")}}><span>◇</span><b>{r[0]}</b><small>{r[1]}</small><em>{all.filter(u=>u.role===r[0]).length} korisnika • {r[2]} modula</em></button>)}</div>}{tab==="Aktivnosti"&&<section className="panel activity-log">{all.slice(0,5).map((u,i)=><button key={u.email} onClick={()=>setSelected(u)}><span>{u.name.split(" ").map(x=>x[0]).join("")}</span><div><b>{u.name}</b><small>{["Promenio status rezervacije DN-2841","Dodao novo vozilo","Otvorio finansijski izveštaj","Ažurirala klijenta","Poziv za pristup je poslat"][i]}</small></div><em>{u.lastActive}</em></button>)}</section>}{invite&&<InviteUser close={()=>setInvite(false)} saved={u=>{setAdded(x=>[u,...x]);setInvite(false)}}/>}{selected&&<UserPanel user={selected} close={()=>setSelected(null)} saved={u=>{setAdded(x=>[u,...x.filter(y=>y.email!==selected.email)]);setSelected(u)}}/>}</>}
function InviteUser({close,saved}:{close:()=>void;saved:(u:U)=>void}){const[form,setForm]=useState({name:"",email:"",role:"Agent",branch:"Beograd",permissions:["Vozila","Rezervacije","Klijenti"]});const[saving,setSaving]=useState(false);const[error,setError]=useState("");const submit=async(e:React.FormEvent)=>{e.preventDefault();setSaving(true);try{const r=await fetch("/api/users",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(form)});const d=await r.json();if(!r.ok)throw new Error(d.error);saved(d.user)}catch(e){setError(e instanceof Error?e.message:"Poziv nije poslat.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer add-vehicle" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>NOVI KORISNIK</small><h2>Pozovi člana tima</h2><form onSubmit={submit}><label>Ime i prezime *<input required value={form.name} onChange={e=>setForm(x=>({...x,name:e.target.value}))}/></label><label>Email *<input required type="email" value={form.email} onChange={e=>setForm(x=>({...x,email:e.target.value}))}/></label><div className="add-form-grid"><label>Uloga<select value={form.role} onChange={e=>setForm(x=>({...x,role:e.target.value}))}><option>Administrator</option><option>Menadžer</option><option>Agent</option><option>Računovođa</option></select></label><label>Poslovnica<select value={form.branch} onChange={e=>setForm(x=>({...x,branch:e.target.value}))}><option>Sve poslovnice</option><option>Beograd</option><option>Novi Sad</option><option>Niš</option></select></label></div>{error&&<div className="form-error">{error}</div>}<div className="modal-actions"><button type="button" className="outline" onClick={close}>Otkaži</button><button className="primary" disabled={saving}>{saving?"Slanje…":"Pošalji poziv"}</button></div></form></aside></div>}
function UserPanel({user,close,saved}:{user:U;close:()=>void;saved:(u:U)=>void}){const initial=safePermissions(user.permissions);const[form,setForm]=useState({...user,permissions:initial as string[]});const[saving,setSaving]=useState(false);const[error,setError]=useState("");const modules=["Vozila","Rezervacije","Klijenti","Finansije","Dokumentacija","Izveštaji","Korisnici"];const toggle=(m:string)=>setForm(x=>({...x,permissions:x.permissions.includes(m)?x.permissions.filter(p=>p!==m):[...x.permissions,m]}));const save=async()=>{setSaving(true);try{const r=await fetch("/api/users",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,originalEmail:user.email})});const d=await r.json();if(!r.ok)throw new Error(d.error);saved(d.user)}catch(e){setError(e instanceof Error?e.message:"Izmene nisu sačuvane.")}finally{setSaving(false)}};return <div className="drawer-wrap" onClick={close}><aside className="drawer user-panel" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={close}>×</button><small>KORISNIČKI NALOG</small><div className="client-hero"><span>{form.name.split(" ").map(x=>x[0]).join("")}</span><div><h2>{form.name}</h2><Badge s={form.status}/></div></div><div className="client-edit"><label>Ime<input value={form.name} onChange={e=>setForm(x=>({...x,name:e.target.value}))}/></label><label>Email<input value={form.email} onChange={e=>setForm(x=>({...x,email:e.target.value}))}/></label><label>Uloga<select value={form.role} onChange={e=>setForm(x=>({...x,role:e.target.value}))}><option>Administrator</option><option>Menadžer</option><option>Agent</option><option>Računovođa</option></select></label><label>Poslovnica<select value={form.branch} onChange={e=>setForm(x=>({...x,branch:e.target.value}))}><option>Sve poslovnice</option><option>Beograd</option><option>Novi Sad</option><option>Niš</option></select></label><label>Status<select value={form.status} onChange={e=>setForm(x=>({...x,status:e.target.value}))}><option>Aktivan</option><option>Pozvan</option><option>Suspendo­van</option></select></label></div><h3 className="permission-title">Dozvole po modulima</h3><div className="permission-list">{modules.map(m=><label key={m}><input type="checkbox" checked={form.permissions.includes(m)} onChange={()=>toggle(m)}/><span><b>{m}</b><small>Pregled i upravljanje modulom</small></span></label>)}</div>{error&&<div className="form-error">{error}</div>}<button className="primary drawer-action" onClick={save} disabled={saving}>{saving?"Čuvanje…":"Sačuvaj korisnika i dozvole"}</button></aside></div>}
function Settings(){const[tab,setTab]=useState("Firma");return <><Head title="Podešavanja" sub="Prilagodite DriveNode vašem poslovanju."/><div className="settings-layout"><nav>{["Firma","Poslovnice","Cenovnik","Dodaci","Načini plaćanja","Porezi i valuta","Obaveštenja","Integracije"].map(x=><button className={tab===x?"active":""} onClick={()=>setTab(x)} key={x}>{x}<span>›</span></button>)}</nav><section className="panel settings-form"><h2>{tab}</h2><p>Osnovni podaci i podešavanja modula.</p><div className="form-grid"><label>Naziv kompanije<input placeholder="Naziv vaše rent-a-car kompanije"/></label><label>PIB<input placeholder="PIB"/></label><label>Matični broj<input placeholder="Matični broj"/></label><label>Telefon<input placeholder="Telefon"/></label><label className="full">Adresa<input placeholder="Adresa sedišta"/></label><label>Email<input placeholder="Email kompanije"/></label><label>Web sajt<input placeholder="Web sajt"/></label></div><div className="form-actions"><button className="outline">Otkaži</button><button className="primary">Sačuvaj izmene</button></div></section></div></>}
function Login({on}:{on:()=>void}){return <div className="login"><section className="login-brand"><div className="brand"><span className="brand-mark">D</span><div><b>DriveNode</b><small>FLEET MANAGER</small></div></div><div><span className="login-pill">DNFM BETA V1</span><h1>Vaša flota.<br/><em>Potpuna kontrola.</em></h1><p>Jednostavnije rezervacije, bolja iskorišćenost i više profita — sve na jednom mestu.</p></div></section><section className="login-form"><form onSubmit={e=>{e.preventDefault();on()}}><div className="login-logo"><span className="brand-mark">D</span></div><h2>Dobro došli nazad</h2><p>Prijavite se na vaš DriveNode nalog.</p><label>Email adresa<input type="email" defaultValue="demo@dnfm.rs"/></label><label>Lozinka<input type="password" defaultValue="drivenode"/></label><div className="remember"><label><input type="checkbox" defaultChecked/> Zapamti me</label><a>Zaboravili ste lozinku?</a></div><button className="primary login-button">Prijavi se</button><small>Demo pristup je unapred popunjen</small></form></section></div>}
function App(){const[logged,setLogged]=useState(false);const[page,setPage]=useState("Pregled");const[v,setV]=useState<V|null>(null);const[b,setB]=useState<B|null>(null);const[newBooking,setNewBooking]=useState(false);const[bookingReturnPage,setBookingReturnPage]=useState("Rezervacije");const[bookingRefresh,setBookingRefresh]=useState(0);const[bookingOverrides,setBookingOverrides]=useState<Record<string,string>>({});const[vehicleAddTrigger,setVehicleAddTrigger]=useState(0);const[clientAddTrigger,setClientAddTrigger]=useState(0);const[q,setQ]=useState("");if(!logged)return <Login on={()=>setLogged(true)}/>;const go=(x:string)=>{setPage(x);setV(null)};const createBooking=()=>{setBookingReturnPage(page);setNewBooking(true)};const addVehicle=()=>{setV(null);setPage("Vozila");setVehicleAddTrigger(x=>x+1)};const addClient=()=>{setV(null);setPage("Klijenti");setClientAddTrigger(x=>x+1)};const bookingSaved=()=>{setNewBooking(false);setPage(bookingReturnPage);setBookingRefresh(x=>x+1)};const statusSaved=(id:string,status:string)=>{setBookingOverrides(x=>({...x,[id]:status}));setBookingRefresh(x=>x+1);setB(null)};let c:React.ReactNode;if(v)c=<VehicleDetail v={v} back={()=>setV(null)}/>;else c=page==="Vozila"?<Vehicles open={setV} addTrigger={vehicleAddTrigger}/>:page==="Rezervacije"?<Reservations open={setB} newReservation={createBooking} refresh={bookingRefresh} overrides={bookingOverrides}/>:page==="Kalendar"?<Calendar open={setB} newReservation={createBooking} refresh={bookingRefresh} overrides={bookingOverrides}/>:page==="Klijenti"?<Clients addTrigger={clientAddTrigger}/>:page.startsWith("Servisi")?<Services/>:page==="Finansije"?<Finance/>:page==="Dokumentacija"?<Documents/>:page==="Izveštaji"?<Reports/>:page.startsWith("Korisnici")?<Users/>:page==="Podešavanja"?<Settings/>:<DashboardLive go={go} openBooking={setB} newReservation={createBooking} addVehicle={addVehicle} newClient={addClient}/>;return <main className="app-shell"><aside className="sidebar"><div className="brand"><span className="brand-mark">D</span><div><b>DriveNode</b><small>FLEET MANAGER</small></div></div><nav>{nav.map((x,i)=><button key={x} className={page===x&&!v?"active":""} onClick={()=>go(x)}><span className="nav-icon">{["◈","▣","▤","▦","◉","⚙","◎","□","◩","◌"][i]}</span>{x}{false&&<em>0</em>}</button>)}</nav><div className="sidebar-bottom"><button onClick={()=>go("Podešavanja")}><span className="nav-icon">⚙</span>Podešavanja</button><div className="profile"><span>AD</span><div><b>Administrator</b><small>Administrator</small></div><i onClick={()=>setLogged(false)}>⋯</i></div></div></aside><section className="content"><header><GlobalSearch openVehicle={setV} openBooking={setB} go={go}/><div className="head-actions"><button onClick={()=>go("Servisi i registracije")} aria-label="Otvori obaveštenja">○</button><button className="primary" onClick={createBooking}>+ Nova rezervacija</button></div></header><div className="page">{c}</div></section>{b&&<BookingPanel b={b} close={()=>setB(null)} saved={statusSaved}/>} {newBooking&&<NewReservationModal close={()=>setNewBooking(false)} saved={bookingSaved}/>}</main>}

export default function Home(){return <AppErrorBoundary><App/></AppErrorBoundary>}
